/**
 * Gestore del Bottom Sheet Mobile a tre stadi (collapsed, half, full)
 */
export class BottomSheet {
  constructor(sheetEl, handleEl) {
    this.sheet = sheetEl;
    this.handle = handleEl;
    this.state = 'collapsed'; // 'collapsed' | 'half' | 'full'
    this.startY = 0;
    this.currentY = 0;
    this.isDragging = false;

    this.init();
  }

  init() {
    this.handle.addEventListener('click', () => {
      if (this.state === 'collapsed') {
        this.setState('half');
      } else if (this.state === 'half') {
        this.setState('full');
      } else {
        this.setState('collapsed');
      }
    });

    // Touch support for drag
    this.handle.addEventListener('touchstart', (e) => this.onTouchStart(e), { passive: true });
    window.addEventListener('touchmove', (e) => this.onTouchMove(e), { passive: false });
    window.addEventListener('touchend', () => this.onTouchEnd());

    // Set initial transform
    this.updateTransform();
  }

  onTouchStart(e) {
    this.isDragging = true;
    this.startY = e.touches[0].clientY;
    this.sheet.style.transition = 'none';
  }

  onTouchMove(e) {
    if (!this.isDragging) return;
    const deltaY = e.touches[0].clientY - this.startY;
    
    // Prevent default scrolling when dragging handle
    if (Math.abs(deltaY) > 5) {
      e.preventDefault();
    }

    const fullHeight = window.innerHeight - 100;
    const halfHeight = fullHeight * 0.55;
    const collapsedHeight = 74;

    let baseHeight = this.getHeightForState(this.state);
    let newHeight = baseHeight - deltaY;

    // Clamp
    newHeight = Math.max(collapsedHeight, Math.min(fullHeight, newHeight));
    const translateY = fullHeight - newHeight;
    this.sheet.style.transform = `translateY(${translateY}px)`;
  }

  onTouchEnd() {
    if (!this.isDragging) return;
    this.isDragging = false;
    this.sheet.style.transition = 'transform 0.3s cubic-bezier(0.16, 1, 0.3, 1)';

    // Determine target state based on current position
    const rect = this.sheet.getBoundingClientRect();
    const visibleHeight = window.innerHeight - rect.top;
    const fullHeight = window.innerHeight - 100;
    const halfHeight = fullHeight * 0.55;

    if (visibleHeight > halfHeight + (fullHeight - halfHeight) / 2) {
      this.setState('full');
    } else if (visibleHeight > 74 + (halfHeight - 74) / 2) {
      this.setState('half');
    } else {
      this.setState('collapsed');
    }
  }

  getHeightForState(state) {
    const fullHeight = window.innerHeight - 100;
    switch (state) {
      case 'full':
        return fullHeight;
      case 'half':
        return fullHeight * 0.55;
      case 'collapsed':
      default:
        return 74;
    }
  }

  setState(state) {
    this.state = state;
    this.sheet.style.transition = 'transform 0.3s cubic-bezier(0.16, 1, 0.3, 1)';
    this.updateTransform();

    // Update aria
    this.handle.setAttribute('aria-expanded', state !== 'collapsed');
  }

  updateTransform() {
    const fullHeight = window.innerHeight - 100;
    const targetHeight = this.getHeightForState(this.state);
    const translateY = fullHeight - targetHeight;
    this.sheet.style.transform = `translateY(${translateY}px)`;
  }
}
