/**
 * REGGIO PNRR — Login Modal Component con Autenticazione a 2 Fattori (MFA / OTP)
 * Include loghi istituzionali: Comune di Reggio Emilia, PNRR Italiadomani e NextGenerationEU
 */

import { VALID_CREDENTIALS } from '../services/authService.js';

export class LoginModal {
  constructor(containerEl, authService, onLoginSuccess) {
    this.container = containerEl;
    this.auth = authService;
    this.onLoginSuccess = onLoginSuccess;

    this.step = 'credentials'; // 'credentials' | 'otp'
    this.email = '';
    this.password = '';
    this.showPassword = false;
    this.credentialError = '';
    this.isSubmitting = false;

    this.otpDigits = ['', '', '', '', '', ''];
    this.otpError = '';
    this.countdown = 60;
    this.canResend = false;
    this.timer = null;

    this.render();
  }

  show() {
    this.step = 'credentials';
    this.email = '';
    this.password = '';
    this.credentialError = '';
    this.otpDigits = ['', '', '', '', '', ''];
    this.otpError = '';
    this.stopTimer();

    this.container.classList.remove('hidden');
    this.render();
  }

  hide() {
    this.stopTimer();
    this.container.classList.add('hidden');
  }

  startTimer() {
    this.stopTimer();
    this.countdown = 60;
    this.canResend = false;
    this.timer = setInterval(() => {
      this.countdown--;
      const countdownEl = this.container.querySelector('#otp-countdown-text');
      if (countdownEl) {
        if (this.countdown > 0) {
          countdownEl.innerHTML = `Nuovo codice tra <strong class="font-mono text-slate-700">${this.countdown}s</strong>`;
        } else {
          this.canResend = true;
          countdownEl.innerHTML = `
            <button type="button" id="btn-resend-otp" class="text-teal hover:text-teal-dark font-black underline cursor-pointer">
              Reinvia codice OTP
            </button>
          `;
          const resendBtn = this.container.querySelector('#btn-resend-otp');
          if (resendBtn) {
            resendBtn.addEventListener('click', () => {
              this.startTimer();
            });
          }
        }
      }
      if (this.countdown <= 0) {
        this.stopTimer();
      }
    }, 1000);
  }

  stopTimer() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  render() {
    this.container.innerHTML = `
      <div class="fixed inset-0 z-[9999] flex items-center justify-center p-3 sm:p-4 bg-slate-900/80 backdrop-blur-md overflow-y-auto custom-scrollbar select-none">
        
        <!-- Modal Card Container -->
        <div class="w-full max-w-lg bg-white rounded-3xl shadow-2xl border border-slate-200/90 overflow-hidden my-auto transform transition-all animate-in fade-in zoom-in-95 duration-200">
          
          <!-- Top Tricolore stripe -->
          <div class="h-1.5 w-full bg-gradient-to-r from-[#009246] via-white to-[#CE2B37]"></div>

          <!-- Card Header: 3 Institutional Logos + Titles -->
          <div class="bg-white p-5 sm:p-6 text-center border-b border-slate-100">
            
            <!-- Two Official Institutional Logos Row -->
            <div class="flex items-center justify-center gap-6 sm:gap-8 mb-4 pb-3 border-b border-slate-100/80 px-2">
              <!-- 1. Comune di Reggio Emilia Logo -->
              <div class="h-11 sm:h-13 flex items-center shrink-0">
                <img 
                  src="${import.meta.env.BASE_URL}reggio-emilia.png" 
                  alt="Comune di Reggio Emilia" 
                  class="h-9 sm:h-11 w-auto object-contain select-none"
                  title="Comune di Reggio Emilia"
                />
              </div>

              <div class="h-8 w-[1px] bg-slate-200 shrink-0"></div>

              <!-- 2. NextGenerationEU Logo -->
              <div class="h-11 sm:h-13 flex items-center shrink-0">
                <img 
                  src="${import.meta.env.BASE_URL}images.png" 
                  alt="Finanziato dall'Unione europea - NextGenerationEU" 
                  class="h-8 sm:h-10 w-auto object-contain select-none"
                  title="NextGenerationEU"
                />
              </div>
            </div>

            <!-- Portal Title & Department -->
            <div class="space-y-0.5">
              <h1 class="text-xl sm:text-2xl font-black tracking-tight text-slate-900">
                <span class="text-teal font-black">RADAR</span> PNRR · Control Room
              </h1>
              <p class="text-xs text-teal font-extrabold uppercase tracking-wider">
                data platform by U.D.P. UNITÀ SPECIALE PER IL PNRR
              </p>
              <p class="text-[11px] text-slate-500 max-w-sm mx-auto leading-tight pt-0.5">
                Comune di Reggio Emilia &bull; Accesso riservato Direzione Generale
              </p>
            </div>
          </div>

          <!-- Dynamic Body Section: Step 1 vs Step 2 -->
          <div id="login-modal-body" class="p-6 sm:p-8 bg-white">
            ${this.renderBodyContent()}
          </div>

          <!-- Institutional AgID Footer -->
          <div class="bg-slate-50 px-6 py-3.5 border-t border-slate-100 text-[11px] text-slate-500 flex items-center justify-between">
            <span class="flex items-center gap-1.5 font-semibold">
              <i class="ph-bold ph-shield-check text-emerald-600 text-sm"></i>
              Conforme AgID / GDPR
            </span>
            <span class="text-slate-400 font-mono text-[10.5px]">D.Lgs. 196/2003 · SSL 256-bit</span>
          </div>

        </div>
      </div>
    `;

    this.bindEvents();
  }

  renderBodyContent() {
    if (this.step === 'credentials') {
      return `
        <!-- PASSO 1: CREDENZIALI ISTITUZIONALI -->
        <form id="credentials-form" class="space-y-4">
          
          <div class="flex items-center justify-between pb-2 border-b border-slate-100">
            <span class="text-xs font-bold uppercase tracking-wider text-slate-700 flex items-center gap-1.5">
              <i class="ph-bold ph-lock-key text-teal text-sm"></i>
              Passo 1 di 2: Credenziali Istituzionali
            </span>
          </div>

          <!-- Error Alert Banner -->
          <div id="credential-error-banner" class="${this.credentialError ? 'flex' : 'hidden'} p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-800 items-start gap-2">
            <i class="ph-bold ph-warning-circle text-rose-600 text-base shrink-0 mt-0.5"></i>
            <span id="credential-error-text">${this.credentialError}</span>
          </div>

          <!-- Email Input -->
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">
              Email Istituzionale
            </label>
            <div class="relative">
              <i class="ph-bold ph-envelope text-slate-400 text-sm absolute left-3 top-3"></i>
              <input
                type="email"
                id="login-email-input"
                required
                value="${this.email}"
                placeholder="nome.cognome@comune.re.it"
                autocomplete="username"
                class="w-full pl-9 pr-3 py-2.5 bg-slate-50 border border-slate-300 rounded-xl text-xs sm:text-sm text-slate-900 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-teal focus:bg-white transition-all shadow-2xs font-medium"
              />
            </div>
          </div>

          <!-- Password Input -->
          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">
              Password
            </label>
            <div class="relative">
              <i class="ph-bold ph-key text-slate-400 text-sm absolute left-3 top-3"></i>
              <input
                type="${this.showPassword ? 'text' : 'password'}"
                id="login-password-input"
                required
                value="${this.password}"
                placeholder="••••••••••••"
                autocomplete="current-password"
                class="w-full pl-9 pr-10 py-2.5 bg-slate-50 border border-slate-300 rounded-xl text-xs sm:text-sm text-slate-900 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-teal focus:bg-white transition-all shadow-2xs font-mono"
              />
              <button
                type="button"
                id="toggle-password-visibility-btn"
                class="absolute right-3 top-2.5 text-slate-400 hover:text-slate-700 cursor-pointer p-1"
                title="${this.showPassword ? 'Nascondi password' : 'Mostra password'}"
              >
                <i class="ph-bold ${this.showPassword ? 'ph-eye-slash' : 'ph-eye'} text-sm"></i>
              </button>
            </div>
          </div>


          <!-- Submit Button -->
          <button
            type="submit"
            id="submit-credentials-btn"
            ${this.isSubmitting ? 'disabled' : ''}
            class="w-full py-2.5 bg-teal hover:bg-teal-dark active:scale-[0.99] text-white font-black rounded-xl text-xs sm:text-sm shadow-md transition-all flex items-center justify-center gap-2 cursor-pointer mt-4 disabled:opacity-75 disabled:cursor-not-allowed"
          >
            ${this.isSubmitting ? `
              <span class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span>
              <span>Verifica credenziali in corso...</span>
            ` : `
              <span>Continua con Verifica OTP (MFA)</span>
              <i class="ph-bold ph-arrow-right text-sm"></i>
            `}
          </button>
        </form>
      `;
    } else {
      return `
        <!-- PASSO 2: VERIFICA 2FA (OTP A 6 CIFRE) -->
        <div class="space-y-4">
          <div class="flex items-center justify-between pb-2 border-b border-slate-100">
            <span class="text-xs font-bold uppercase tracking-wider text-slate-700 flex items-center gap-1.5">
              <i class="ph-bold ph-device-mobile text-teal text-sm"></i>
              Passo 2 di 2: Verifica 2FA (OTP)
            </span>
            <button
              type="button"
              id="back-to-credentials-btn"
              class="text-[11px] text-slate-500 hover:text-slate-800 underline cursor-pointer font-bold"
            >
              &larr; Indietro
            </button>
          </div>

          <div class="text-center py-2">
            <div class="inline-flex p-3 bg-teal-soft text-teal rounded-full border border-teal/20 mb-2 shadow-xs">
              <i class="ph-bold ph-shield-check text-2xl"></i>
            </div>
            <h3 class="text-sm font-black text-slate-900">
              Codice Temporaneo di Sicurezza (OTP)
            </h3>
            <p class="text-xs text-slate-500 mt-1 max-w-xs mx-auto leading-normal">
              È stato generato un codice OTP monouso a 6 cifre per l'utenza<br/>
              <strong class="text-slate-800">${this.email}</strong>
            </p>
          </div>

          <!-- Error Alert Banner -->
          <div id="otp-error-banner" class="${this.otpError ? 'flex' : 'hidden'} p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-800 items-start gap-2">
            <i class="ph-bold ph-warning-circle text-rose-600 text-base shrink-0 mt-0.5"></i>
            <span id="otp-error-text">${this.otpError}</span>
          </div>

          <!-- 6 Digits OTP Input Boxes -->
          <div class="flex justify-center items-center gap-1.5 sm:gap-2.5 py-2">
            ${[0, 1, 2, 3, 4, 5].map(idx => `
              <input
                type="text"
                inputmode="numeric"
                pattern="[0-9]*"
                maxlength="1"
                data-otp-idx="${idx}"
                value="${this.otpDigits[idx] || ''}"
                autocomplete="one-time-code"
                class="otp-digit-input w-11 h-13 sm:w-12 sm:h-14 text-center text-xl font-black font-mono bg-slate-50 border-2 border-slate-300 rounded-xl text-slate-900 focus:outline-none focus:border-teal focus:bg-white focus:ring-2 focus:ring-teal/30 transition-all shadow-xs"
              />
            `).join('')}
          </div>


          <!-- Verify Button -->
          <button
            type="button"
            id="verify-otp-btn"
            ${this.otpDigits.join('').length !== 6 || this.isSubmitting ? 'disabled' : ''}
            class="w-full py-2.5 bg-teal hover:bg-teal-dark disabled:bg-slate-300 disabled:cursor-not-allowed text-white font-black rounded-xl text-xs sm:text-sm shadow-md transition-all flex items-center justify-center gap-2 cursor-pointer mt-2"
          >
            ${this.isSubmitting ? `
              <span class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span>
              <span>Verifica codice in corso...</span>
            ` : `
              <i class="ph-bold ph-check-circle text-base"></i>
              <span>Conferma &amp; Accedi al Cruscotto</span>
            `}
          </button>

          <!-- Resend Helper & Countdown -->
          <div class="flex items-center justify-between text-xs text-slate-500 pt-3 border-t border-slate-100">
            <span id="otp-countdown-text">
              Nuovo codice tra <strong class="font-mono text-slate-700">${this.countdown}s</strong>
            </span>
            <span class="text-[11px] text-slate-400 flex items-center gap-1">
              <i class="ph-bold ph-device-mobile-camera"></i>
              App IO / SMS PA
            </span>
          </div>
        </div>
      `;
    }
  }

  bindEvents() {
    const body = this.container.querySelector('#login-modal-body');
    if (!body) return;

    if (this.step === 'credentials') {
      const form = body.querySelector('#credentials-form');
      const emailInput = body.querySelector('#login-email-input');
      const passwordInput = body.querySelector('#login-password-input');
      const togglePwdBtn = body.querySelector('#toggle-password-visibility-btn');

      if (togglePwdBtn && passwordInput) {
        togglePwdBtn.addEventListener('click', () => {
          this.showPassword = !this.showPassword;
          passwordInput.type = this.showPassword ? 'text' : 'password';
          const icon = togglePwdBtn.querySelector('i');
          if (icon) {
            icon.className = `ph-bold ${this.showPassword ? 'ph-eye-slash' : 'ph-eye'} text-sm`;
          }
        });
      }


      if (form && emailInput && passwordInput) {
        form.addEventListener('submit', (e) => {
          e.preventDefault();
          this.email = emailInput.value.trim();
          this.password = passwordInput.value;
          this.credentialError = '';

          const submitBtn = body.querySelector('#submit-credentials-btn');
          if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.innerHTML = `
              <span class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span>
              <span>Verifica credenziali in corso...</span>
            `;
          }

          setTimeout(() => {
            if (this.auth.validateCredentials(this.email, this.password)) {
              this.step = 'otp';
              this.render();
              this.startTimer();
              // Auto-focus first OTP box
              const firstBox = this.container.querySelector('input[data-otp-idx="0"]');
              if (firstBox) firstBox.focus();
            } else {
              this.credentialError = 'Credenziali non valide. Verificare indirizzo email istituzionale e password.';
              this.render();
            }
          }, 450);
        });
      }
    } else {
      // Step 2: OTP
      const backBtn = body.querySelector('#back-to-credentials-btn');
      if (backBtn) {
        backBtn.addEventListener('click', () => {
          this.stopTimer();
          this.step = 'credentials';
          this.render();
        });
      }


      const inputs = body.querySelectorAll('.otp-digit-input');
      inputs.forEach((input, idx) => {
        // Input event
        input.addEventListener('input', (e) => {
          const val = e.target.value;
          if (!/^\d*$/.test(val)) {
            e.target.value = '';
            return;
          }

          const digit = val.slice(-1);
          e.target.value = digit;
          this.otpDigits[idx] = digit;
          this.otpError = '';
          const banner = body.querySelector('#otp-error-banner');
          if (banner) banner.classList.add('hidden');

          // Auto-focus next input
          if (digit && idx < 5) {
            const nextInp = body.querySelector(`input[data-otp-idx="${idx + 1}"]`);
            if (nextInp) nextInp.focus();
          }

          const verifyBtn = body.querySelector('#verify-otp-btn');
          const fullOtp = this.otpDigits.join('');
          if (verifyBtn) {
            verifyBtn.disabled = fullOtp.length !== 6;
          }

          if (fullOtp.length === 6) {
            this.verifyOtpCode(fullOtp);
          }
        });

        // Keydown (Backspace navigation)
        input.addEventListener('keydown', (e) => {
          if (e.key === 'Backspace' && !input.value && idx > 0) {
            const prevInp = body.querySelector(`input[data-otp-idx="${idx - 1}"]`);
            if (prevInp) {
              prevInp.focus();
              prevInp.value = '';
              this.otpDigits[idx - 1] = '';
            }
          }
        });

        // Paste support
        input.addEventListener('paste', (e) => {
          e.preventDefault();
          const pasted = (e.clipboardData || window.clipboardData).getData('text').trim();
          if (/^\d{6}$/.test(pasted)) {
            const digits = pasted.split('');
            this.otpDigits = digits;
            inputs.forEach((inp, i) => {
              inp.value = digits[i] || '';
            });
            this.verifyOtpCode(pasted);
          }
        });
      });

      const verifyBtn = body.querySelector('#verify-otp-btn');
      if (verifyBtn) {
        verifyBtn.addEventListener('click', () => {
          const fullOtp = this.otpDigits.join('');
          if (fullOtp.length === 6) {
            this.verifyOtpCode(fullOtp);
          }
        });
      }
    }
  }

  verifyOtpCode(code) {
    const body = this.container.querySelector('#login-modal-body');
    const verifyBtn = body ? body.querySelector('#verify-otp-btn') : null;
    if (verifyBtn) {
      verifyBtn.disabled = true;
      verifyBtn.innerHTML = `
        <span class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span>
        <span>Verifica codice in corso...</span>
      `;
    }

    setTimeout(() => {
      if (this.auth.validateOtp(code)) {
        const user = this.auth.login(true);
        this.stopTimer();
        this.hide();
        if (this.onLoginSuccess) {
          this.onLoginSuccess(user);
        }
      } else {
        this.otpError = 'Codice OTP errato o scaduto. Inserire il codice a 6 cifre corretto.';
        if (verifyBtn) {
          verifyBtn.disabled = false;
          verifyBtn.innerHTML = `
            <i class="ph-bold ph-check-circle text-base"></i>
            <span>Conferma &amp; Accedi al Cruscotto</span>
          `;
        }
        const banner = this.container.querySelector('#otp-error-banner');
        const text = this.container.querySelector('#otp-error-text');
        if (banner && text) {
          text.innerText = this.otpError;
          banner.classList.remove('hidden');
        }
      }
    }, 450);
  }
}
