/**
 * REGGIO PNRR / RadarPNRR — Servizio Dati e Aggregatore Progetti
 * Centralizza interrogazioni, filtri, statistiche e calcoli per la cartografia analitica
 */

import { PROJECTS_DATA, PNRR_MISSIONS, MACRO_THEMES } from '../data/projectsData.js';
import { calculatePnrrPulse, calculateDataQualitySummary } from './etlService.js';
import { AMBITI_STRUTTURA } from '../data/reggioEmiliaData.js';

export class ProjectService {
  constructor(initialData = PROJECTS_DATA) {
    // Esclusivamente progetti del Comune di Reggio Emilia (NO TERRITORIO)
    this.allProjects = initialData.filter(p => 
      p.isComune === true || 
      (p.implementingBody && p.implementingBody.toLowerCase().includes('comune di reggio'))
    );
  }

  /**
   * Filtra la collezione dei progetti in base a tutti i criteri attivi
   */
  filterProjects(filters = {}) {
    const {
      type = 'tutti',            // 'tutti' | 'opere' | 'digitale_servizi' | 'servizi'
      status = 'tutti',          // 'tutti' | 'in_corso' | 'completato' | 'in_ritardo' | 'da_verificare'
      mission = null,            // null | 'M1' ... 'M6'
      area = null,               // null | 'Ambito A' ... | 'Centro Storico'
      district = null,           // null | nome quartiere
      theme = null,              // null | 'scuole' | 'mobilita' ...
      query = ''                 // stringa di ricerca libera
    } = filters;

    const cleanQuery = (query || '').trim().toLowerCase();

    return this.allProjects.filter(p => {

      // 2. Filtro Tipologia: Opere vs Digitale / Servizi
      if (type === 'opere' || type === 'opera') {
        if (p.projectType !== 'opera') return false;
      } else if (type === 'digitale_servizi' || type === 'digitale') {
        if (p.projectType !== 'digitale' && p.projectType !== 'servizi') return false;
      } else if (type === 'servizi') {
        if (p.projectType !== 'servizi') return false;
      }

      // 3. Filtro Stato
      if (status && status !== 'tutti') {
        if (p.status !== status) return false;
      }

      // 4. Filtro Missione PNRR
      if (mission && mission !== 'tutte') {
        if (p.mission !== mission) return false;
      }

      // 5. Filtro Ambito Territoriale / Quartiere
      const areaFilter = area || district;
      const isAllArea = !areaFilter || 
        areaFilter === 'Tutti i quartieri' || 
        areaFilter === 'Tutta Reggio Emilia' || 
        areaFilter === 'Tutti gli ambiti' || 
        areaFilter === 'Tutti gli Ambiti' ||
        areaFilter === 'Tutti' || 
        areaFilter === 'tutti' || 
        areaFilter === 'all';

      if (!isAllArea) {
        if (p.area !== areaFilter && p.district !== areaFilter) {
          const matchedAmbito = AMBITI_STRUTTURA.find(a => a.name === areaFilter);
          if (!matchedAmbito || !matchedAmbito.quartieri.includes(p.district)) {
            return false;
          }
        }
      }

      // 6. Filtro Macro-Tema
      if (theme && theme !== 'tutti') {
        if (p.theme !== theme) return false;
      }

      // 7. Ricerca Testuale Full-Text
      if (cleanQuery) {
        const titleMatch = (p.title || '').toLowerCase().includes(cleanQuery);
        const cupMatch = (p.cup || '').toLowerCase().includes(cleanQuery);
        const clpMatch = (p.clp || '').toLowerCase().includes(cleanQuery);
        const addrMatch = (p.address || '').toLowerCase().includes(cleanQuery);
        const distMatch = (p.district || '').toLowerCase().includes(cleanQuery);
        const areaMatch = (p.area || '').toLowerCase().includes(cleanQuery);
        const implMatch = (p.implementingBody || '').toLowerCase().includes(cleanQuery);
        const descMatch = (p.description || '').toLowerCase().includes(cleanQuery);
        const rupMatch = (p.rup || '').toLowerCase().includes(cleanQuery);
        const minMatch = (p.ministry || '').toLowerCase().includes(cleanQuery);

        if (!titleMatch && !cupMatch && !clpMatch && !addrMatch && !distMatch && !areaMatch && !implMatch && !descMatch && !rupMatch && !minMatch) {
          return false;
        }
      }

      return true;
    });
  }

  /**
   * Calcola i KPI di alto livello per la KPI Bar
   */
  getKPIs(projects = this.allProjects) {
    let totalFunding = 0;
    let totalPnrr = 0;
    let totalMunicipal = 0;
    let totalFoi = 0;
    let totalOther = 0;
    let totalPayments = 0;
    let opereCount = 0;
    let digitaleCount = 0;
    let serviziCount = 0;

    projects.forEach(p => {
      totalFunding += (p.totalFunding || 0);
      totalPnrr += (p.pnrrFunding || 0);
      totalMunicipal += (p.municipalFunding || 0);
      totalFoi += (p.foiFunding || 0);
      totalOther += (p.otherFunding || (p.municipalFunding || 0) + (p.foiFunding || 0));
      totalPayments += (p.payments || 0);

      if (p.projectType === 'opera') opereCount++;
      else if (p.projectType === 'digitale') digitaleCount++;
      else if (p.projectType === 'servizi') serviziCount++;
    });

    const paymentPercentage = totalFunding > 0
      ? Math.round((totalPayments / totalFunding) * 1000) / 10
      : 0;

    const pulse = calculatePnrrPulse(projects);
    const dataQuality = calculateDataQualitySummary(projects);

    return {
      totalProjects: projects.length,
      totalFunding,
      totalPnrr,
      totalMunicipal,
      totalFoi,
      totalOther,
      totalPayments,
      paymentPercentage,
      opereCount,
      digitaleCount,
      serviziCount,
      pulse,
      dataQuality
    };
  }

  /**
   * CHOROPLETH ANALITICA PER AMBITO
   * Ricalcola per ciascun Ambito i valori della metrica selezionata a partire
   * ESCLUSIVAMENTE dai dati correntemente filtrati.
   * Restituisce una mappa: { "Ambito A": { count, totalFunding, pnrrFunding, payments, avgProgress, metricValue, ... }, ... }
   */
  getAmbitiAnalyticalData(projects = this.allProjects, metric = 'funding') {
    const ambitiMap = {};

    AMBITI_STRUTTURA.forEach(a => {
      ambitiMap[a.name] = {
        name: a.name,
        lettera: a.lettera,
        color: a.color,
        quartieri: a.quartieri,
        count: 0,
        totalFunding: 0,
        pnrrFunding: 0,
        payments: 0,
        totalProgress: 0,
        avgProgress: 0,
        metricValue: 0,
        projects: []
      };
    });

    projects.forEach(p => {
      let targetAmbitoName = p.area;
      if (!ambitiMap[targetAmbitoName]) {
        // Cerca per quartiere
        const found = AMBITI_STRUTTURA.find(a => a.quartieri && a.quartieri.includes(p.district));
        if (found) {
          targetAmbitoName = found.name;
        }
      }

      if (ambitiMap[targetAmbitoName]) {
        const item = ambitiMap[targetAmbitoName];
        item.count++;
        item.totalFunding += (p.totalFunding || 0);
        item.pnrrFunding += (p.pnrrFunding || 0);
        item.payments += (p.payments || 0);
        item.totalProgress += (p.progress || 0);
        item.projects.push(p);
      }
    });

    // Calcolo metriche e medie
    Object.values(ambitiMap).forEach(item => {
      item.avgProgress = item.count > 0 ? Math.round(item.totalProgress / item.count) : 0;

      if (metric === 'funding') {
        item.metricValue = item.totalFunding;
      } else if (metric === 'payments') {
        item.metricValue = item.payments;
      } else if (metric === 'projects') {
        item.metricValue = item.count;
      } else if (metric === 'progress') {
        item.metricValue = item.avgProgress;
      }
    });

    return ambitiMap;
  }

  /**
   * Ricalcola dinamicamente la scala cromatica e le 5 soglie
   * in base ai valori reali risultanti dai filtri attivi.
   */
  calculateDynamicChoroplethScale(ambitiData = {}, metric = 'funding') {
    const values = Object.values(ambitiData).map(a => a.metricValue || 0);
    const maxVal = Math.max(...values, 0);

    const colors = ['#A2DFE8', '#5AC8D8', '#2AA5B4', '#0E8C9B', '#085C66'];

    if (metric === 'funding') {
      // € Investiti
      const step = maxVal > 0 ? maxVal / 5 : 2000000;
      const t1 = Math.max(1000000, Math.round(step / 100000) * 100000);
      const t2 = Math.max(t1 * 2, Math.round((step * 2) / 100000) * 100000);
      const t3 = Math.max(t2 + 1000000, Math.round((step * 3) / 100000) * 100000);
      const t4 = Math.max(t3 + 2000000, Math.round((step * 4) / 100000) * 100000);

      return {
        metric: 'funding',
        unit: 'M€',
        metricTitle: '€ Investiti (PNRR + Cofinanziamenti)',
        thresholds: [
          { max: t1, label: `< ${(t1 / 1000000).toFixed(1)} M€`, color: colors[0], fillOpacity: 0.35 },
          { max: t2, label: `${(t1 / 1000000).toFixed(1)} – ${(t2 / 1000000).toFixed(1)} M€`, color: colors[1], fillOpacity: 0.45 },
          { max: t3, label: `${(t2 / 1000000).toFixed(1)} – ${(t3 / 1000000).toFixed(1)} M€`, color: colors[2], fillOpacity: 0.55 },
          { max: t4, label: `${(t3 / 1000000).toFixed(1)} – ${(t4 / 1000000).toFixed(1)} M€`, color: colors[3], fillOpacity: 0.65 },
          { max: Infinity, label: `> ${(t4 / 1000000).toFixed(1)} M€`, color: colors[4], fillOpacity: 0.78 }
        ],
        getValue: (a) => a ? a.totalFunding : 0,
        formatValue: (val) => `${(val / 1000000).toFixed(1)} M€`
      };
    } else if (metric === 'payments') {
      // Pagamenti erogati
      const step = maxVal > 0 ? maxVal / 5 : 1000000;
      const t1 = Math.max(500000, Math.round(step / 100000) * 100000);
      const t2 = Math.max(t1 * 2, Math.round((step * 2) / 100000) * 100000);
      const t3 = Math.max(t2 + 500000, Math.round((step * 3) / 100000) * 100000);
      const t4 = Math.max(t3 + 1000000, Math.round((step * 4) / 100000) * 100000);

      return {
        metric: 'payments',
        unit: 'M€',
        metricTitle: 'Pagamenti Erogati',
        thresholds: [
          { max: t1, label: `< ${(t1 / 1000000).toFixed(1)} M€`, color: colors[0], fillOpacity: 0.35 },
          { max: t2, label: `${(t1 / 1000000).toFixed(1)} – ${(t2 / 1000000).toFixed(1)} M€`, color: colors[1], fillOpacity: 0.45 },
          { max: t3, label: `${(t2 / 1000000).toFixed(1)} – ${(t3 / 1000000).toFixed(1)} M€`, color: colors[2], fillOpacity: 0.55 },
          { max: t4, label: `${(t3 / 1000000).toFixed(1)} – ${(t4 / 1000000).toFixed(1)} M€`, color: colors[3], fillOpacity: 0.65 },
          { max: Infinity, label: `> ${(t4 / 1000000).toFixed(1)} M€`, color: colors[4], fillOpacity: 0.78 }
        ],
        getValue: (a) => a ? a.payments : 0,
        formatValue: (val) => `${(val / 1000000).toFixed(1)} M€`
      };
    } else if (metric === 'projects') {
      // N. Progetti
      return {
        metric: 'projects',
        unit: 'progetti',
        metricTitle: 'Numero di Progetti',
        thresholds: [
          { max: 1, label: '1 progetto', color: colors[0], fillOpacity: 0.35 },
          { max: 3, label: '2 – 3 progetti', color: colors[1], fillOpacity: 0.45 },
          { max: 6, label: '4 – 6 progetti', color: colors[2], fillOpacity: 0.55 },
          { max: 10, label: '7 – 10 progetti', color: colors[3], fillOpacity: 0.65 },
          { max: Infinity, label: '> 10 progetti', color: colors[4], fillOpacity: 0.78 }
        ],
        getValue: (a) => a ? a.count : 0,
        formatValue: (val) => `${val} progetti`
      };
    } else {
      // Avanzamento medio %
      return {
        metric: 'progress',
        unit: '%',
        metricTitle: 'Avanzamento Medio',
        thresholds: [
          { max: 25, label: '0 – 25%', color: colors[0], fillOpacity: 0.35 },
          { max: 50, label: '25 – 50%', color: colors[1], fillOpacity: 0.45 },
          { max: 70, label: '50 – 70%', color: colors[2], fillOpacity: 0.55 },
          { max: 85, label: '70 – 85%', color: colors[3], fillOpacity: 0.65 },
          { max: Infinity, label: '85 – 100%', color: colors[4], fillOpacity: 0.78 }
        ],
        getValue: (a) => a ? a.avgProgress : 0,
        formatValue: (val) => `${val}%`
      };
    }
  }

  /**
   * Riepilogo aggregato per Missione PNRR calcolato ESCLUSIVAMENTE sui progetti passati
   */
  getMissionsSummary(projects = this.allProjects) {
    const summary = {};

    Object.keys(PNRR_MISSIONS).forEach(mCode => {
      summary[mCode] = {
        ...PNRR_MISSIONS[mCode],
        count: 0,
        totalFunding: 0,
        pnrrFunding: 0,
        payments: 0,
        paymentPercentage: 0
      };
    });

    projects.forEach(p => {
      if (summary[p.mission]) {
        summary[p.mission].count++;
        summary[p.mission].totalFunding += (p.totalFunding || 0);
        summary[p.mission].pnrrFunding += (p.pnrrFunding || 0);
        summary[p.mission].payments += (p.payments || 0);
      }
    });

    Object.values(summary).forEach(item => {
      item.paymentPercentage = item.totalFunding > 0
        ? Math.round((item.payments / item.totalFunding) * 1000) / 10
        : 0;
    });

    return summary;
  }

  /**
   * Riepilogo aggregato per Ambiti Territoriali
   */
  getAmbitiSummary(projects = this.allProjects) {
    const ambitiMap = {};

    AMBITI_STRUTTURA.forEach(a => {
      ambitiMap[a.name] = {
        name: a.name,
        lettera: a.lettera,
        count: 0,
        totalFunding: 0,
        pnrrFunding: 0
      };
    });

    projects.forEach(p => {
      if (ambitiMap[p.area]) {
        ambitiMap[p.area].count++;
        ambitiMap[p.area].totalFunding += (p.totalFunding || 0);
        ambitiMap[p.area].pnrrFunding += (p.pnrrFunding || 0);
      }
    });

    return ambitiMap;
  }

  /**
   * Top N progetti per importo
   */
  getTopInvestments(projects = this.allProjects, limit = 10) {
    return [...projects]
      .sort((a, b) => (b.totalFunding || 0) - (a.totalFunding || 0))
      .slice(0, limit);
  }

  /**
   * Distribuzione per Macro-Tema
   */
  getThemeDistribution(projects = this.allProjects) {
    const themeMap = {};
    MACRO_THEMES.forEach(t => {
      themeMap[t.id] = {
        ...t,
        count: 0,
        totalFunding: 0,
        payments: 0
      };
    });

    projects.forEach(p => {
      const tId = p.theme || 'altro';
      if (themeMap[tId]) {
        themeMap[tId].count++;
        themeMap[tId].totalFunding += (p.totalFunding || 0);
        themeMap[tId].payments += (p.payments || 0);
      }
    });

    return Object.values(themeMap).filter(t => t.count > 0);
  }

  /**
   * Distribuzione per Soggetto Attuatore (Comune vs altri)
   */
  getImplementingBodiesSummary(projects = this.allProjects) {
    let comuneTotal = 0;
    let comuneCount = 0;
    let othersTotal = 0;
    let othersCount = 0;
    const othersByEntity = {};

    projects.forEach(p => {
      const isComune = p.isComune === true || (p.implementingBody && p.implementingBody.toLowerCase().includes('comune di reggio'));
      if (isComune) {
        comuneTotal += (p.totalFunding || 0);
        comuneCount++;
      } else {
        othersTotal += (p.totalFunding || 0);
        othersCount++;
        const name = p.implementingBody || 'Altro Ente';
        othersByEntity[name] = (othersByEntity[name] || 0) + (p.totalFunding || 0);
      }
    });

    return {
      comune: {
        name: "Comune di Reggio nell'Emilia",
        count: comuneCount,
        totalFunding: comuneTotal,
        percentage: (comuneTotal + othersTotal) > 0 ? Math.round((comuneTotal / (comuneTotal + othersTotal)) * 100) : 0
      },
      others: {
        name: "Altri Soggetti Attuatori",
        count: othersCount,
        totalFunding: othersTotal,
        percentage: (comuneTotal + othersTotal) > 0 ? Math.round((othersTotal / (comuneTotal + othersTotal)) * 100) : 0,
        entities: othersByEntity
      }
    };
  }

  /**
   * Distribuzione scadenze previste
   */
  getTimelineDistribution(projects = this.allProjects) {
    const years = { '2023': 0, '2024': 0, '2025': 0, '2026': 0, 'Oltre 2026': 0 };
    projects.forEach(p => {
      if (p.expectedEndDate) {
        const year = p.expectedEndDate.substring(0, 4);
        if (years[year] !== undefined) {
          years[year]++;
        } else if (parseInt(year, 10) > 2026) {
          years['Oltre 2026']++;
        }
      }
    });
    return years;
  }
}
