/**
 * REGGIO PNRR / RadarPNRR — Project Card Component
 * Genera il markup HTML di una singola card progetto per la lista laterale
 */

import { PNRR_MISSIONS, STATUS_LABELS } from '../data/projectsData.js';

export function renderProjectCard(project, isActive = false) {
  const missionInfo = PNRR_MISSIONS[project.mission] || PNRR_MISSIONS.M5;
  const statusInfo = STATUS_LABELS[project.status] || STATUS_LABELS.in_corso;

  // Format funding: es. 11,90 M€ o 850 k€
  const formattedFunding = project.totalFunding >= 1000000
    ? (project.totalFunding / 1000000).toLocaleString('it-IT', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' M€'
    : Math.round(project.totalFunding / 1000).toLocaleString('it-IT') + ' k€';

  const payPct = typeof project.paymentPercentage === 'number'
    ? project.paymentPercentage.toFixed(1)
    : (project.totalFunding > 0 ? ((project.payments / project.totalFunding) * 100).toFixed(1) : '0.0');

  const isComune = project.isComune;

  const updateBadgeLabel = project.sourceUpdateDate 
    ? (project.sourceUpdateDate.includes('13 Giugno 2026') ? '13/06/2026 (ReGiS)' : (project.sourceUpdateDate.includes('26 Febbraio 2026') ? '26/02/2026 (OpenPNRR)' : project.sourceUpdateDate.split('(')[0].trim()))
    : '2026';

  return `
    <button 
      type="button" 
      class="project-card-item group relative flex w-full flex-col gap-2 rounded-card border text-left transition-all p-3.5 focus:outline-none select-none ${
        isActive 
          ? 'border-teal bg-teal-soft/80 shadow-card ring-1 ring-teal' 
          : 'border-ink/8 bg-white hover:bg-surface-hover hover:border-teal/40'
      }"
      data-cup="${project.cup}"
    >
      <!-- Top Badges Row: Mission & Status -->
      <div class="flex items-center justify-between gap-1.5 w-full">
        <!-- Mission Pill -->
        <span 
          class="inline-flex items-center gap-1 text-[9.5px] font-black uppercase tracking-wider px-2 py-0.5 rounded-md"
          style="background-color: ${missionInfo.lightColor}; color: ${missionInfo.color};"
        >
          <i class="ph-bold ${missionInfo.icon}"></i>
          <span>${project.mission} · ${missionInfo.shortName}</span>
        </span>

        <!-- Status Badge -->
        <span class="inline-flex items-center text-[9px] font-extrabold uppercase px-2 py-0.5 rounded border ${statusInfo.badgeClass}">
          ${statusInfo.label}
        </span>
      </div>

      <!-- Title & Location -->
      <div class="min-w-0 flex-1 w-full">
        <h4 class="text-[13.5px] font-black text-ink leading-snug group-hover:text-teal transition-colors line-clamp-2">
          ${project.title}
        </h4>

        <!-- RUP & Ministry Line -->
        <div class="flex items-center gap-1.5 text-[10.5px] mt-1 text-ink-muted">
          <span class="inline-flex items-center gap-1 font-bold text-teal-800 shrink-0">
            <i class="ph-bold ph-user text-teal text-xs"></i>
            <span>${project.rup || 'RUP N.D.'}</span>
          </span>
          ${project.ministry ? `
            <span class="text-ink/20 shrink-0">•</span>
            <span class="truncate text-[10px] text-ink-muted" title="${project.ministry}">
              ${project.ministry.split('–')[0].split('-')[0].trim()}
            </span>
          ` : ''}
        </div>
        
        <p class="text-[11px] text-ink-muted mt-1 flex items-center gap-1.5 truncate">
          <i class="ph-bold ph-map-pin text-teal shrink-0"></i>
          <span>${project.address ? `${project.address} · ` : ''}<strong>${project.district}</strong>${project.area ? ` (${project.area})` : ''}</span>
        </p>
      </div>

      <!-- Financial Value & Breakdown -->
      <div class="flex items-center justify-between gap-2 pt-1 border-t border-ink/8 text-left w-full">
        <div class="flex flex-col">
          <span class="text-[13px] font-black text-ink">
            € ${formattedFunding}
          </span>
          <span class="text-[9px] font-bold text-ink-muted uppercase tracking-wider">
            ${(project.municipalFunding || 0) > 0 ? `PNRR: € ${Math.round((project.pnrrFunding || 0)/1000)}k · Com: € ${Math.round((project.municipalFunding || 0)/1000)}k` : 'Totale Investimento'}
          </span>
        </div>

        <div class="text-right flex flex-col items-end">
          <span class="inline-flex items-center gap-1 text-[9.5px] font-extrabold px-2 py-0.5 rounded-full ${isComune ? 'bg-teal-surface text-teal font-black' : 'bg-ink/5 text-ink-muted'}">
            ${isComune ? '<i class="ph-bold ph-buildings"></i> Comune RE' : project.implementingBody}
          </span>
        </div>
      </div>

      <!-- Payments Progress Bar -->
      <div class="w-full pt-1">
        <div class="flex items-center justify-between text-[10px] font-bold text-ink/70 mb-1">
          <span class="text-[9px] text-ink-muted">Pagamenti erogati</span>
          <span class="text-emerald-700 font-black">${payPct}%</span>
        </div>
        <div class="w-full h-1.5 rounded-full bg-ink/10 overflow-hidden">
          <div 
            class="h-full bg-emerald-500 rounded-full transition-all duration-300"
            style="width: ${Math.min(100, parseFloat(payPct))}%;"
          ></div>
        </div>
      </div>

      <!-- Bottom Meta: CUP, Type and Update reference -->
      <div class="flex items-center justify-between text-[9.5px] text-ink-muted pt-1 border-t border-ink/4">
        <div class="flex items-center gap-1.5 font-mono">
          <span class="bg-ink/5 px-1.5 py-0.5 rounded font-bold text-ink/70">
            CUP: ${project.cup}
          </span>
          <span class="text-teal font-sans font-bold capitalize text-[9px]">
            ${project.projectType === 'opera' ? 'Opera' : project.projectType}
          </span>
        </div>
        <span class="inline-flex items-center gap-1 text-[9px] font-semibold text-teal-800 bg-teal-50 border border-teal-200/60 px-1.5 py-0.5 rounded" title="Data di aggiornamento dataset fonte: ${project.sourceUpdateDate || 'Febbraio – Giugno 2026'}">
          <i class="ph-bold ph-calendar-blank text-teal"></i> U.D.P. 2026
        </span>
      </div>
    </button>
  `;
}
