/**
 * REGGIO PNRR — Authentication Service
 * Gestione sessione, credenziali istituzionali e verifica MFA (OTP)
 */

export const VALID_CREDENTIALS = {
  email: 'francesca.mattioli@comune.re.it',
  password: 'Av3ng3rs*R3ggio',
  otp: '123456'
};

export const AUTH_USER_PROFILE = {
  email: 'francesca.mattioli@comune.re.it',
  name: 'Dott.ssa Francesca Mattioli',
  shortName: 'Dott.ssa F. Mattioli',
  initials: 'FM',
  role: 'Direzione Generale & Controllo di Gestione',
  department: 'Comune di Reggio Emilia',
  accessLevel: 'Amministrazione & Asseverazione PNRR'
};

const STORAGE_KEY = 'reggio_pnrr_auth_session';

export class AuthService {
  constructor() {
    this.currentUser = this.loadSession();
  }

  loadSession() {
    try {
      const raw = sessionStorage.getItem(STORAGE_KEY) || localStorage.getItem(STORAGE_KEY);
      if (raw) {
        return JSON.parse(raw);
      }
    } catch (e) {
      console.warn('Errore lettura sessione auth:', e);
    }
    return null;
  }

  isAuthenticated() {
    return Boolean(this.currentUser && this.currentUser.email);
  }

  getCurrentUser() {
    return this.currentUser;
  }

  validateCredentials(email, password) {
    const cleanEmail = (email || '').trim().toLowerCase();
    return (
      cleanEmail === VALID_CREDENTIALS.email.toLowerCase() &&
      password === VALID_CREDENTIALS.password
    );
  }

  validateOtp(otp) {
    const cleanOtp = (otp || '').trim();
    return cleanOtp === VALID_CREDENTIALS.otp;
  }

  login(remember = true) {
    const sessionData = {
      ...AUTH_USER_PROFILE,
      lastLogin: new Date().toLocaleString('it-IT')
    };

    this.currentUser = sessionData;

    try {
      const serialized = JSON.stringify(sessionData);
      sessionStorage.setItem(STORAGE_KEY, serialized);
      if (remember) {
        localStorage.setItem(STORAGE_KEY, serialized);
      }
    } catch (e) {
      console.error('Errore salvataggio sessione auth:', e);
    }

    return sessionData;
  }

  logout() {
    this.currentUser = null;
    try {
      sessionStorage.removeItem(STORAGE_KEY);
      localStorage.removeItem(STORAGE_KEY);
    } catch (e) {
      console.warn('Errore pulizia sessione auth:', e);
    }
  }
}
