/**
 * REGGIO PNRR / RadarPNRR — Modalità Narrativa: "LA CITTÀ CHE CAMBIA"
 * Strumento di comunicazione pubblica e trasparenza civica.
 * Traduce gli atti amministrativi e i codici CUP nei 7 grandi pilastri della trasformazione urbana di Reggio Emilia:
 * Scuole, Mobilità, Rigenerazione Urbana, Ambiente, Digitale, Sociale, Salute.
 */

import { MACRO_THEMES, PNRR_MISSIONS } from '../data/projectsData.js';

export class CityChangeModal {
  constructor(containerEl, projectService, onProjectSelect) {
    this.container = containerEl;
    this.projectService = projectService;
    this.onProjectSelect = onProjectSelect;
    this.activeTheme = 'scuole'; // default
  }

  show() {
    this.render();
    this.container.classList.remove('hidden');
    document.body.classList.add('overflow-hidden');
  }

  hide() {
    this.container.classList.add('hidden');
    document.body.classList.remove('overflow-hidden');
  }

  formatMillions(amount) {
    if (!amount) return '0 M€';
    if (amount >= 1000000) {
      return (amount / 1000000).toFixed(1) + ' M€';
    }
    return Math.round(amount / 1000) + ' k€';
  }

  render() {
    const allProjects = this.projectService.allProjects;
    const themesData = this.projectService.getThemeDistribution(allProjects);

    // Selected theme details
    const currentThemeInfo = MACRO_THEMES.find(t => t.id === this.activeTheme) || MACRO_THEMES[0];
    const themeProjects = allProjects.filter(p => p.theme === this.activeTheme);

    let themeFunding = 0;
    let themePnrr = 0;
    let themePayments = 0;
    themeProjects.forEach(p => {
      themeFunding += (p.totalFunding || 0);
      themePnrr += (p.pnrrFunding || 0);
      themePayments += (p.payments || 0);
    });
    const themePayPct = themeFunding > 0 ? ((themePayments / themeFunding) * 100).toFixed(1) : 0;

    this.container.innerHTML = `
      <div class="fixed inset-0 z-[100] flex items-center justify-center p-2 sm:p-4 md:p-6 select-none">
        <!-- Backdrop -->
        <div class="modal-backdrop absolute inset-0 bg-ink/65 backdrop-blur-md" id="citychange-backdrop"></div>

        <!-- Main Modal Container -->
        <div class="modal-content relative z-10 w-full max-w-5xl max-h-[94dvh] overflow-y-auto rounded-panel bg-white p-5 md:p-8 shadow-float border border-ink/8 text-left custom-scrollbar">
          
          <!-- Header -->
          <div class="flex items-start justify-between gap-4 pb-4 border-b border-ink/8">
            <div>
              <div class="flex items-center gap-2 mb-1">
                <span class="inline-flex h-2 w-2 rounded-full bg-teal animate-ping"></span>
                <span class="text-[11px] font-black uppercase tracking-wider text-teal">Comunicazione Civica & Trasparenza</span>
              </div>
              <h2 class="text-2xl md:text-3xl font-black text-ink tracking-tight">
                La Città che Cambia
              </h2>
              <p class="text-xs md:text-sm text-ink-muted mt-1 max-w-2xl leading-relaxed">
                Dal piano alla città: come le risorse del Piano Nazionale di Ripresa e Resilienza stanno rigenerando quartieri, scuole, spazi pubblici e servizi a Reggio Emilia.
              </p>
            </div>

            <button 
              type="button" 
              id="citychange-close-btn" 
              class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-ink/5 text-ink/60 hover:bg-ink/10 hover:text-ink transition-colors"
              aria-label="Chiudi La Città che Cambia"
            >
              <i class="ph-bold ph-x text-lg"></i>
            </button>
          </div>

          <!-- Thematic Navigation Tabs -->
          <div class="flex items-center gap-2 overflow-x-auto scrollbar-none py-3 border-b border-ink/8">
            ${MACRO_THEMES.map(t => {
              const isSel = this.activeTheme === t.id;
              const count = allProjects.filter(p => p.theme === t.id).length;
              return `
                <button 
                  type="button" 
                  class="theme-tab-btn flex items-center gap-2 px-3.5 py-2 rounded-full border text-xs font-bold whitespace-nowrap transition-all ${
                    isSel 
                      ? 'bg-teal text-white border-teal shadow-sm font-black' 
                      : 'bg-surface-subtle border-ink/8 text-ink hover:bg-teal-soft hover:text-teal'
                  }"
                  data-theme="${t.id}"
                >
                  <i class="ph-bold ${t.icon}"></i>
                  <span>${t.label}</span>
                  <span class="h-4.5 px-1.5 rounded-full ${isSel ? 'bg-white/25 text-white' : 'bg-ink/10 text-ink/70'} text-[10px] flex items-center justify-center font-black">
                    ${count}
                  </span>
                </button>
              `;
            }).join('')}
          </div>

          <!-- Theme Overview Header Strip -->
          <div class="grid grid-cols-2 sm:grid-cols-4 gap-3 my-5 p-4 rounded-panel bg-teal-soft/80 border border-teal/20 text-ink">
            <div>
              <span class="text-[10px] font-extrabold uppercase text-teal block">Tema Selezionato</span>
              <span class="text-base md:text-lg font-black text-ink block mt-0.5">${currentThemeInfo.label}</span>
            </div>
            <div>
              <span class="text-[10px] font-extrabold uppercase text-teal block">Investimento Complessivo</span>
              <span class="text-base md:text-lg font-black text-ink block mt-0.5">${this.formatMillions(themeFunding)}</span>
            </div>
            <div>
              <span class="text-[10px] font-extrabold uppercase text-teal block">Risorse PNRR</span>
              <span class="text-base md:text-lg font-black text-blue-700 block mt-0.5">${this.formatMillions(themePnrr)}</span>
            </div>
            <div>
              <span class="text-[10px] font-extrabold uppercase text-teal block">Pagamenti Erogati</span>
              <span class="text-base md:text-lg font-black text-emerald-700 block mt-0.5">${themePayPct}%</span>
            </div>
          </div>

          <!-- Interventions Grid for the Theme -->
          <div>
            <div class="flex items-center justify-between mb-3">
              <h3 class="text-sm font-black uppercase tracking-wider text-ink">
                Interventi e Opere sul Territorio (${themeProjects.length})
              </h3>
              <span class="text-xs text-ink-muted">Tocca un intervento per visualizzarne la scheda e localizzarlo</span>
            </div>

            <div class="grid grid-cols-1 md:grid-cols-2 gap-3">
              ${themeProjects.map(p => {
                const m = PNRR_MISSIONS[p.mission] || PNRR_MISSIONS.M5;
                const pay = p.totalFunding > 0 ? ((p.payments / p.totalFunding) * 100).toFixed(0) : 0;
                return `
                  <button 
                    type="button" 
                    class="theme-project-card p-4 rounded-card border border-ink/8 bg-white hover:bg-teal-soft hover:border-teal/40 text-left transition-all group flex flex-col justify-between"
                    data-cup="${p.cup}"
                  >
                    <div>
                      <div class="flex items-center justify-between gap-2 mb-1.5">
                        <span class="inline-flex items-center gap-1 text-[9.5px] font-black uppercase px-2 py-0.5 rounded" style="background-color: ${m.lightColor}; color: ${m.color};">
                          ${p.mission} · ${m.shortName}
                        </span>
                        <span class="text-[10px] font-bold text-teal">${p.district}</span>
                      </div>

                      <h4 class="text-sm font-black text-ink leading-snug group-hover:text-teal transition-colors">
                        ${p.title}
                      </h4>
                      <p class="text-xs text-ink-muted mt-1 line-clamp-2 leading-relaxed">
                        ${p.description || p.component}
                      </p>
                    </div>

                    <div class="mt-3 pt-2.5 border-t border-ink/8 flex items-center justify-between text-xs">
                      <div>
                        <span class="text-[10px] text-ink-muted uppercase block">Investimento</span>
                        <strong class="text-ink font-black text-[13px]">${this.formatMillions(p.totalFunding)}</strong>
                      </div>
                      <div class="text-right">
                        <span class="text-[10px] text-ink-muted uppercase block">Avanzamento</span>
                        <strong class="text-emerald-600 font-black text-[13px]">${pay}% pagato</strong>
                      </div>
                    </div>
                  </button>
                `;
              }).join('')}
            </div>
          </div>

        </div>
      </div>
    `;

    // Events
    const closeBtn = this.container.querySelector('#citychange-close-btn');
    if (closeBtn) closeBtn.addEventListener('click', () => this.hide());

    const backdrop = this.container.querySelector('#citychange-backdrop');
    if (backdrop) backdrop.addEventListener('click', () => this.hide());

    this.container.querySelectorAll('.theme-tab-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        this.activeTheme = btn.getAttribute('data-theme');
        this.render();
      });
    });

    this.container.querySelectorAll('.theme-project-card').forEach(card => {
      card.addEventListener('click', () => {
        const cup = card.getAttribute('data-cup');
        const project = allProjects.find(p => p.cup === cup);
        if (project && this.onProjectSelect) {
          this.hide();
          this.onProjectSelect(project);
        }
      });
    });
  }
}
