/**
 * REGGIO PNRR / RadarPNRR — Search Bar Component
 * Cerca contemporaneamente per:
 * - Titolo progetto
 * - CUP (Codice Unico Progetto)
 * - Codice Locale Progetto (CLP)
 * - Indirizzo e via
 * - Quartiere
 * - Ambito territoriale
 * - Soggetto attuatore
 * Supporta anche geocodifica indirizzi a Reggio Emilia (Photon).
 */

import { ApiService } from '../services/apiService.js';
import { PNRR_MISSIONS } from '../data/projectsData.js';

export class SearchBar {
  constructor(containerEl, allProjects, onProjectSelect, onAddressSelect, onFilterQuery) {
    this.container = containerEl;
    this.allProjects = allProjects;
    this.onProjectSelect = onProjectSelect;
    this.onAddressSelect = onAddressSelect;
    this.onFilterQuery = onFilterQuery;
    this.selectedIndex = -1;
    this.projectResults = [];
    this.addressResults = [];
    this.debounceTimer = null;

    this.render();
    this.bindEvents();
  }

  setProjects(projects) {
    this.allProjects = projects;
  }

  render() {
    this.container.innerHTML = `
      <div class="relative w-full">
        <div class="flex h-10 md:h-11 items-center gap-2 rounded-full bg-white/95 backdrop-blur-md pl-3.5 pr-2 shadow-card border border-ink/8 transition-all focus-within:shadow-float focus-within:border-teal">
          <i class="ph ph-magnifying-glass text-[17px] text-teal shrink-0"></i>
          <input 
            type="text" 
            id="search-input"
            role="combobox" 
            aria-autocomplete="list" 
            aria-expanded="false" 
            placeholder="Cerca progetto, CUP, RUP, ministero, via..." 
            class="min-w-0 flex-1 bg-transparent text-[12.5px] md:text-[13px] font-semibold text-ink placeholder:font-normal placeholder:text-ink/40 focus:outline-none"
            autocomplete="off"
          />
          <button 
            type="button" 
            id="search-clear-btn" 
            class="hidden h-7 w-7 shrink-0 items-center justify-center rounded-full text-ink/40 hover:bg-ink/5 hover:text-ink transition-colors"
            aria-label="Cancella ricerca"
          >
            <i class="ph-bold ph-x text-[13px]"></i>
          </button>
        </div>

        <!-- Suggestion Dropdown -->
        <div 
          id="search-suggestions" 
          class="hidden absolute left-0 right-0 top-[calc(100%+8px)] z-50 max-h-[380px] overflow-y-auto rounded-panel bg-white p-2 shadow-float border border-ink/8 text-left custom-scrollbar"
        ></div>
      </div>
    `;

    this.input = this.container.querySelector('#search-input');
    this.clearBtn = this.container.querySelector('#search-clear-btn');
    this.suggestionsList = this.container.querySelector('#search-suggestions');
  }

  bindEvents() {
    this.input.addEventListener('input', (e) => {
      clearTimeout(this.debounceTimer);
      const query = e.target.value;
      if (this.onFilterQuery) {
        this.onFilterQuery(query);
      }
      this.debounceTimer = setTimeout(() => this.handleInput(query), 200);
    });

    this.input.addEventListener('keydown', (e) => this.handleKeydown(e));
    this.clearBtn.addEventListener('click', () => this.clearSearch());

    // Close suggestions on outside click
    document.addEventListener('click', (e) => {
      if (!this.container.contains(e.target)) {
        this.hideSuggestions();
      }
    });

    this.input.addEventListener('focus', () => {
      if (this.input.value.trim().length > 0) {
        this.handleInput(this.input.value);
      }
    });
  }

  async handleInput(query) {
    const q = query.trim();

    if (q.length === 0) {
      this.clearBtn.classList.add('hidden');
      this.hideSuggestions();
      return;
    }

    this.clearBtn.classList.remove('hidden');

    // 1. Search internal projects
    const qLower = q.toLowerCase();
    this.projectResults = this.allProjects.filter(p => {
      return (
        (p.title || '').toLowerCase().includes(qLower) ||
        (p.cup || '').toLowerCase().includes(qLower) ||
        (p.rup || '').toLowerCase().includes(qLower) ||
        (p.ministry || '').toLowerCase().includes(qLower) ||
        (p.clp || '').toLowerCase().includes(qLower) ||
        (p.address || '').toLowerCase().includes(qLower) ||
        (p.district || '').toLowerCase().includes(qLower) ||
        (p.area || '').toLowerCase().includes(qLower) ||
        (p.implementingBody || '').toLowerCase().includes(qLower) ||
        (p.theme || '').toLowerCase().includes(qLower)
      );
    }).slice(0, 6);

    // 2. Search Photon OSM Addresses in Reggio Emilia if query is long enough
    this.addressResults = [];
    if (q.length >= 3 && !q.startsWith('C') && !q.startsWith('c')) {
      try {
        const addresses = await ApiService.searchAddress(q);
        this.addressResults = addresses.slice(0, 3);
      } catch (err) {
        this.addressResults = [];
      }
    }

    this.renderSuggestions();
  }

  renderSuggestions() {
    const hasProjects = this.projectResults.length > 0;
    const hasAddresses = this.addressResults.length > 0;

    if (!hasProjects && !hasAddresses) {
      this.suggestionsList.innerHTML = `
        <div class="px-4 py-3 text-center text-xs text-ink/60">
          Nessun progetto o via trovata con "<strong>${this.escapeHtml(this.input.value)}</strong>"
        </div>
      `;
      this.showSuggestions();
      return;
    }

    let html = '';

    // Projects Section
    if (hasProjects) {
      html += `
        <div class="px-2 py-1 text-[10px] font-extrabold uppercase tracking-wider text-teal">
          Progetti PNRR (${this.projectResults.length})
        </div>
      `;

      this.projectResults.forEach((p, idx) => {
        const m = PNRR_MISSIONS[p.mission] || PNRR_MISSIONS.M5;
        const fundingFormatted = p.totalFunding >= 1000000 
          ? (p.totalFunding / 1000000).toFixed(1) + ' M€' 
          : Math.round(p.totalFunding / 1000) + ' k€';

        html += `
          <button 
            type="button" 
            class="suggestion-item w-full text-left rounded-card p-2 hover:bg-teal-soft flex items-start gap-2.5 transition-colors"
            data-type="project"
            data-cup="${p.cup}"
            data-index="${idx}"
          >
            <div class="h-7 w-7 rounded-md flex items-center justify-center shrink-0 mt-0.5" style="background-color: ${m.lightColor}; color: ${m.color};">
              <i class="ph-bold ${m.icon} text-xs"></i>
            </div>
            <div class="min-w-0 flex-1 leading-tight">
              <div class="flex items-center justify-between gap-1">
                <span class="text-[12px] font-bold text-ink truncate">${p.title}</span>
                <span class="text-[11px] font-black text-teal shrink-0">${fundingFormatted}</span>
              </div>
              <p class="text-[10px] text-ink-muted mt-0.5 truncate">
                <span class="font-mono text-ink/70">CUP: ${p.cup}</span> · ${p.district} (${p.area})
              </p>
            </div>
          </button>
        `;
      });
    }

    // Addresses Section
    if (hasAddresses) {
      if (hasProjects) {
        html += `<div class="h-px bg-ink/8 my-1.5"></div>`;
      }
      html += `
        <div class="px-2 py-1 text-[10px] font-extrabold uppercase tracking-wider text-ink-muted">
          Indirizzi a Reggio Emilia
        </div>
      `;

      this.addressResults.forEach((addr, idx) => {
        const actualIdx = this.projectResults.length + idx;
        html += `
          <button 
            type="button" 
            class="suggestion-item w-full text-left rounded-card p-2 hover:bg-teal-soft flex items-center gap-2.5 transition-colors"
            data-type="address"
            data-index="${actualIdx}"
          >
            <i class="ph-bold ph-map-pin text-teal text-base shrink-0"></i>
            <div class="min-w-0 flex-1 leading-tight">
              <p class="text-[12px] font-bold text-ink truncate">${addr.name}</p>
              <p class="text-[10px] text-ink-muted truncate">${addr.city || 'Reggio Emilia'}</p>
            </div>
          </button>
        `;
      });
    }

    this.suggestionsList.innerHTML = html;
    this.showSuggestions();

    // Attach click handlers
    this.suggestionsList.querySelectorAll('.suggestion-item').forEach(btn => {
      btn.addEventListener('click', () => {
        const type = btn.getAttribute('data-type');
        if (type === 'project') {
          const cup = btn.getAttribute('data-cup');
          const p = this.allProjects.find(x => x.cup === cup);
          if (p && this.onProjectSelect) {
            this.input.value = p.title;
            this.hideSuggestions();
            this.onProjectSelect(p);
          }
        } else if (type === 'address') {
          const idx = parseInt(btn.getAttribute('data-index'), 10) - this.projectResults.length;
          const addr = this.addressResults[idx];
          if (addr && this.onAddressSelect) {
            this.input.value = addr.name;
            this.hideSuggestions();
            this.onAddressSelect(addr);
          }
        }
      });
    });
  }

  showSuggestions() {
    this.suggestionsList.classList.remove('hidden');
    this.input.setAttribute('aria-expanded', 'true');
  }

  hideSuggestions() {
    this.suggestionsList.classList.add('hidden');
    this.input.setAttribute('aria-expanded', 'false');
    this.selectedIndex = -1;
  }

  clearSearch() {
    this.input.value = '';
    this.clearBtn.classList.add('hidden');
    this.hideSuggestions();
    if (this.onFilterQuery) {
      this.onFilterQuery('');
    }
  }

  handleKeydown(e) {
    const items = this.suggestionsList.querySelectorAll('.suggestion-item');
    if (items.length === 0) return;

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      this.selectedIndex = (this.selectedIndex + 1) % items.length;
      this.highlightItem(items);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      this.selectedIndex = (this.selectedIndex - 1 + items.length) % items.length;
      this.highlightItem(items);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (this.selectedIndex >= 0 && this.selectedIndex < items.length) {
        items[this.selectedIndex].click();
      }
    } else if (e.key === 'Escape') {
      this.hideSuggestions();
    }
  }

  highlightItem(items) {
    items.forEach((item, idx) => {
      if (idx === this.selectedIndex) {
        item.classList.add('bg-teal-soft');
        item.scrollIntoView({ block: 'nearest' });
      } else {
        item.classList.remove('bg-teal-soft');
      }
    });
  }

  escapeHtml(str) {
    const div = document.createElement('div');
    div.innerText = str;
    return div.innerHTML;
  }
}
