/**
 * REGGIO PNRR / RadarPNRR — Applicazione Principale
 * Coordinatore generale: Map WebGIS, KPI Bar, Left Sidebar, Right Sidebar,
 * Search Bar, Detail Drawer, Analytics Dashboard, La Città che Cambia, Info Modal.
 */

import './styles/main.css';
import { RadarPnrrMap } from './components/map.js';
import { ProjectService } from './services/projectService.js';
import { KPIBar } from './components/kpiBar.js';
import { LeftSidebar } from './components/leftSidebar.js';
import { RightSidebar } from './components/rightSidebar.js';
import { SearchBar } from './components/searchBar.js';
import { ProjectDetailModal } from './components/projectDetailModal.js';
import { AnalyticsModal } from './components/analyticsModal.js';
import { CityChangeModal } from './components/cityChangeModal.js';
import { InfoModal } from './components/infoModal.js';
import { BottomSheet } from './components/bottomSheet.js';
import { renderProjectCard } from './components/projectCard.js';
import { ActiveFilterChips } from './components/activeFilterChips.js';
import { AuthService } from './services/authService.js';
import { LoginModal } from './components/loginModal.js';

class RadarPnrrApp {
  constructor() {
    this.authService = new AuthService();
    this.projectService = new ProjectService();
    this.activeProject = null;

    this.activeFilters = {
      type: 'tutti',             // 'tutti' | 'opere' | 'digitale_servizi'
      status: 'tutti',           // 'tutti' | 'in_corso' | 'completato' | 'in_ritardo'
      mission: null,             // null | 'M1' ... 'M6'
      area: null,                // null | 'Ambito A' ... | quartiere
      district: null,            // null | quartiere
      theme: null,               // null | 'scuole' ...
      query: ''
    };

    this.currentChoroplethMetric = 'funding'; // 'funding' | 'projects' | 'payments' | 'progress'
    this.filteredProjects = [...this.projectService.allProjects];

    this.init();
  }

  init() {
    // 1. Inizializza Mappa WebGIS Fullscreen
    this.map = new RadarPnrrMap('map-container', {
      onProjectSelect: (project) => this.selectProject(project),
      onQuartiereSelect: (quartiereName) => this.selectArea(quartiereName),
      onAmbitoSelect: (ambitoName) => this.selectArea(ambitoName)
    });

    // 2. Inizializza KPI Bar (Sotto Header)
    this.kpiBar = new KPIBar(
      document.getElementById('kpi-bar-container'),
      (pulse) => {
        // Al click su PNRR Pulse apri la modale info / analisi
        this.infoModal.show();
      }
    );

    // 2b. Inizializza Active Filter Chips Bar (Filtri attivi + Azzera filtri)
    this.activeFilterChips = new ActiveFilterChips(
      document.getElementById('active-filter-chips-container'),
      {
        onRemoveFilter: (key) => this.removeFilter(key),
        onResetAll: () => this.resetAllFilters()
      }
    );

    // 3. Inizializza Modali & Overlays
    this.detailModal = new ProjectDetailModal(
      document.getElementById('detail-modal-container'),
      {
        onClose: () => {
          this.activeProject = null;
          this.map.setActiveMarker(null);
          this.rightSidebar.setActiveCup(null);
        },
        onCenterOnMap: (project) => {
          this.map.focusProject(project);
        }
      }
    );

    this.infoModal = new InfoModal(document.getElementById('info-modal-container'));
    this.analyticsModal = new AnalyticsModal(
      document.getElementById('analytics-modal-container'),
      this.projectService,
      (project) => this.selectProject(project)
    );
    this.cityChangeModal = new CityChangeModal(
      document.getElementById('citychange-modal-container'),
      this.projectService,
      (project) => this.selectProject(project)
    );

    // 3b. Inizializza Login Modal con MFA (2FA)
    this.loginModal = new LoginModal(
      document.getElementById('login-modal-container'),
      this.authService,
      (user) => this.onLoginSuccess(user)
    );

    // Verifica stato autenticazione all'avvio
    if (!this.authService.isAuthenticated()) {
      this.loginModal.show();
    }
    this.updateUserHeaderPill(this.authService.getCurrentUser());

    // 4. Inizializza Search Bar con Ricerca Universale
    this.searchBar = new SearchBar(
      document.getElementById('search-bar-container'),
      this.projectService.allProjects,
      (project) => this.selectProject(project),
      (address) => {
        this.map.showAddressMarker(address.lat, address.lng, address.name);
      },
      (searchQuery) => {
        this.activeFilters.query = searchQuery;
        this.applyFilters();
      }
    );

    // 5. Inizializza Left Sidebar ("Investimenti & Territorio")
    this.leftSidebar = new LeftSidebar(
      document.getElementById('legend-container'),
      {
        onAreaSelect: (area) => this.selectArea(area),
        onMissionSelect: (mission) => this.selectMission(mission),
        onChoroplethMetricChange: (metric) => {
          this.currentChoroplethMetric = metric;
          this.updateChoroplethLayer();
        },
        onToggleChoropleth: (visible) => {
          this.map.setChoroplethVisible(visible);
        },
        onBasemapChange: (basemap) => {
          this.map.setBasemap(basemap);
        }
      }
    );

    // 6. Inizializza Right Sidebar ("Progetti PNRR")
    const desktopSidebarContainer = document.getElementById('desktop-sidebar-panel');
    this.rightSidebar = new RightSidebar(
      desktopSidebarContainer,
      (project) => this.selectProject(project),
      (filterChange) => {
        this.activeFilters = { ...this.activeFilters, ...filterChange };
        this.syncTopTypeButtons();
        this.applyFilters();
      }
    );

    // 7. Inizializza Mobile Bottom Sheet
    const mobileSheetEl = document.getElementById('mobile-bottom-sheet');
    const mobileHandleEl = document.getElementById('mobile-sheet-handle');
    if (mobileSheetEl && mobileHandleEl) {
      this.bottomSheet = new BottomSheet(mobileSheetEl, mobileHandleEl);
    }

    // 8. Collega Eventi Header & Controlli Mappa
    this.bindHeaderAndControls();

    // 9. Esegui primo calcolo e render
    this.applyFilters();
  }

  bindHeaderAndControls() {
    // Header Buttons
    const cityChangeBtn = document.getElementById('city-change-btn');
    if (cityChangeBtn) {
      cityChangeBtn.addEventListener('click', () => {
        this.cityChangeModal.show();
      });
    }

    const analyticsBtn = document.getElementById('analytics-btn');
    if (analyticsBtn) {
      analyticsBtn.addEventListener('click', () => {
        this.analyticsModal.show(this.filteredProjects);
      });
    }

    const infoModalBtn = document.getElementById('info-modal-btn');
    if (infoModalBtn) {
      infoModalBtn.addEventListener('click', () => {
        this.infoModal.show();
      });
    }

    const sourcesBadgeBtn = document.getElementById('sources-info-trigger-btn');
    if (sourcesBadgeBtn) {
      sourcesBadgeBtn.addEventListener('click', () => {
        this.infoModal.show();
      });
    }

    // Logout Button
    const logoutBtn = document.getElementById('auth-logout-btn');
    if (logoutBtn) {
      logoutBtn.addEventListener('click', () => {
        this.authService.logout();
        this.updateUserHeaderPill(null);
        this.loginModal.show();
      });
    }

    // Universal Type Pills: [ TUTTI ] [ OPERE ] [ SERVIZI / DIGITALE ]
    document.querySelectorAll('.type-pill-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const type = btn.getAttribute('data-type');
        this.activeFilters.type = type;
        this.syncTopTypeButtons();
        this.rightSidebar.setFiltersState({ type });
        this.applyFilters();
      });
    });

    // Reset Ambito Floating Pill
    const resetAreaBtn = document.getElementById('active-ambito-reset-btn');
    if (resetAreaBtn) {
      resetAreaBtn.addEventListener('click', () => {
        this.selectArea(null);
      });
    }

    // Fit Bounds / Center Map
    const fitBoundsBtn = document.getElementById('fit-bounds-btn');
    if (fitBoundsBtn) {
      fitBoundsBtn.addEventListener('click', () => {
        this.selectArea(null);
        this.map.resetToDefaultView();
      });
    }

    // Geolocation Locate Me
    const locateMeBtn = document.getElementById('locate-me-btn');
    if (locateMeBtn) {
      locateMeBtn.addEventListener('click', () => {
        if (!navigator.geolocation) {
          alert('Geolocalizzazione non supportata dal browser.');
          return;
        }
        locateMeBtn.classList.add('animate-pulse');
        navigator.geolocation.getCurrentPosition(
          (pos) => {
            locateMeBtn.classList.remove('animate-pulse');
            this.map.setUserLocation(pos.coords.latitude, pos.coords.longitude, pos.coords.accuracy);
          },
          (err) => {
            locateMeBtn.classList.remove('animate-pulse');
            alert('Impossibile rilevare la posizione GPS. Verifica i permessi di localizzazione.');
          },
          { enableHighAccuracy: true, timeout: 8000 }
        );
      });
    }

    // Desktop Sidebar Collapse & Expand
    const toggleSidebarBtn = document.getElementById('toggle-right-sidebar-btn');
    const expandSidebarBtn = document.getElementById('expand-sidebar-btn');
    const desktopPanel = document.getElementById('desktop-sidebar-panel');
    const topNavBar = document.getElementById('top-nav-bar');
    const mapControlsDeck = document.getElementById('map-controls-deck');

    if (toggleSidebarBtn && expandSidebarBtn && desktopPanel) {
      toggleSidebarBtn.addEventListener('click', () => {
        desktopPanel.classList.add('translate-x-[calc(100%+24px)]');
        expandSidebarBtn.classList.remove('hidden');
        if (topNavBar) {
          topNavBar.classList.remove('md:right-[456px]');
          topNavBar.classList.add('md:right-4');
        }
        if (mapControlsDeck) {
          mapControlsDeck.classList.remove('md:right-[456px]');
          mapControlsDeck.classList.add('md:right-4');
        }
      });

      expandSidebarBtn.addEventListener('click', () => {
        desktopPanel.classList.remove('translate-x-[calc(100%+24px)]');
        expandSidebarBtn.classList.add('hidden');
        if (topNavBar) {
          topNavBar.classList.add('md:right-[456px]');
          topNavBar.classList.remove('md:right-4');
        }
        if (mapControlsDeck) {
          mapControlsDeck.classList.add('md:right-[456px]');
          mapControlsDeck.classList.remove('md:right-4');
        }
      });
    }
  }

  syncTopTypeButtons() {
    document.querySelectorAll('.type-pill-btn').forEach(btn => {
      const type = btn.getAttribute('data-type');
      if (type === this.activeFilters.type) {
        btn.className = 'type-pill-btn px-2.5 py-0.5 md:py-1 rounded-full transition-all bg-teal text-white shadow-xs font-black';
      } else {
        btn.className = 'type-pill-btn px-2.5 py-0.5 md:py-1 rounded-full transition-all text-ink/70 hover:text-ink font-bold';
      }
    });
  }

  onLoginSuccess(user) {
    this.updateUserHeaderPill(user);
  }

  updateUserHeaderPill(user) {
    const pill = document.getElementById('auth-user-pill');
    const nameEl = document.getElementById('auth-user-name');
    if (user) {
      if (nameEl) nameEl.innerText = user.shortName || user.name;
      if (pill) pill.classList.remove('hidden');
    } else {
      if (pill) pill.classList.add('hidden');
    }
  }

  selectProject(project) {
    this.activeProject = project;
    this.map.focusProject(project);
    this.rightSidebar.setActiveCup(project.cup);
    this.detailModal.show(project);
  }

  selectArea(areaName) {
    const isAll = !areaName || 
      areaName === 'Tutta Reggio Emilia' || 
      areaName === 'Tutti i quartieri' || 
      areaName === 'Tutti gli ambiti' || 
      areaName === 'Tutti gli Ambiti' ||
      areaName === 'Tutti' || 
      areaName === 'tutti' || 
      areaName === 'all';

    const cleanArea = isAll ? null : areaName;

    this.activeFilters.area = cleanArea;
    this.activeFilters.district = cleanArea;

    // Update Floating Pill
    const pill = document.getElementById('active-ambito-pill');
    const nameEl = document.getElementById('active-ambito-name');
    if (pill && nameEl) {
      if (cleanArea) {
        nameEl.innerText = cleanArea;
        pill.classList.remove('hidden');
      } else {
        pill.classList.add('hidden');
      }
    }

    // Map Zoom and Highlight
    this.map.highlightArea(cleanArea);
    this.leftSidebar.setActiveArea(cleanArea);

    this.applyFilters();
  }

  selectMission(missionCode) {
    this.activeFilters.mission = missionCode;
    this.leftSidebar.setActiveMission(missionCode);
    this.rightSidebar.setFiltersState({ mission: missionCode });
    this.applyFilters();
  }

  removeFilter(key) {
    if (key === 'type') {
      this.activeFilters.type = 'tutti';
    } else if (key === 'mission') {
      this.activeFilters.mission = null;
      this.leftSidebar.setActiveMission(null);
    } else if (key === 'area') {
      this.selectArea(null);
      return;
    } else if (key === 'status') {
      this.activeFilters.status = 'tutti';
    } else if (key === 'query') {
      this.activeFilters.query = '';
      if (this.searchBar) {
        this.searchBar.clearSearch();
      }
    }
    this.syncTopTypeButtons();
    this.rightSidebar.setFiltersState(this.activeFilters);
    this.applyFilters();
  }

  resetAllFilters() {
    this.activeFilters = {
      type: 'tutti',
      status: 'tutti',
      mission: null,
      area: null,
      district: null,
      theme: null,
      query: ''
    };
    this.activeProject = null;
    if (this.searchBar) {
      this.searchBar.clearSearch();
    }
    this.map.setActiveMarker(null);
    this.map.resetQuartieriStyle();
    this.map.resetToDefaultView();
    this.syncTopTypeButtons();
    this.rightSidebar.setFiltersState(this.activeFilters);
    this.leftSidebar.setActiveArea(null);
    this.leftSidebar.setActiveMission(null);

    const pill = document.getElementById('active-ambito-pill');
    if (pill) pill.classList.add('hidden');

    this.applyFilters();
  }

  updateChoroplethLayer() {
    const ambitiData = this.projectService.getAmbitiAnalyticalData(
      this.filteredProjects,
      this.currentChoroplethMetric
    );
    const scale = this.projectService.calculateDynamicChoroplethScale(
      ambitiData,
      this.currentChoroplethMetric
    );

    this.map.updateChoropleth(ambitiData, scale);
    this.leftSidebar.updateData(
      ambitiData,
      this.projectService.getMissionsSummary(this.filteredProjects),
      scale,
      this.activeFilters.area,
      this.activeFilters.mission,
      this.currentChoroplethMetric
    );
  }

  applyFilters() {
    // 1. Filtra la collezione dei progetti con logica combinata AND
    this.filteredProjects = this.projectService.filterProjects(this.activeFilters);

    // 2. Calcola KPI aggiornati e aggiorna la barra superiore
    const kpis = this.projectService.getKPIs(this.filteredProjects);
    this.kpiBar.update(kpis);

    // 3. Aggiorna i marker della mappa
    const activeCup = this.activeProject ? this.activeProject.cup : null;
    this.map.setProjects(this.filteredProjects, activeCup);

    // 4. Aggiorna il layer coropletico analitico e la sidebar sinistra
    this.updateChoroplethLayer();

    // 5. Aggiorna la Right Sidebar dei progetti
    this.rightSidebar.setProjects(
      this.filteredProjects,
      activeCup,
      this.projectService.allProjects.length
    );
    this.rightSidebar.setFiltersState(this.activeFilters);

    // 6. Aggiorna la barra chip dei filtri attivi
    if (this.activeFilterChips) {
      this.activeFilterChips.update(this.activeFilters, this.filteredProjects.length);
    }

    // 7. Aggiorna badge e lista mobile
    const badge = document.getElementById('filter-counter-badge');
    if (badge) {
      badge.innerText = `${this.filteredProjects.length} progetti`;
    }

    const mobileCount = document.getElementById('mobile-projects-count');
    if (mobileCount) {
      mobileCount.innerText = `${this.filteredProjects.length} progetti PNRR`;
    }

    const mobileListContainer = document.getElementById('mobile-projects-list');
    if (mobileListContainer) {
      mobileListContainer.innerHTML = this.filteredProjects.map(p => {
        return renderProjectCard(p, p.cup === activeCup);
      }).join('');

      mobileListContainer.querySelectorAll('.project-card-item').forEach(card => {
        card.addEventListener('click', () => {
          const cup = card.getAttribute('data-cup');
          const p = this.filteredProjects.find(x => x.cup === cup);
          if (p) this.selectProject(p);
        });
      });
    }

    // 8. Se la dashboard Analisi è aperta, aggiorna grafici in tempo reale
    const analyticsContainer = document.getElementById('analytics-modal-container');
    if (analyticsContainer && !analyticsContainer.classList.contains('hidden') && this.analyticsModal) {
      this.analyticsModal.render(this.filteredProjects);
    }
  }
}

// Inizializza l'applicazione al caricamento del DOM
document.addEventListener('DOMContentLoaded', () => {
  window.app = new RadarPnrrApp();
});
