/**
 * REGGIO PNRR / RadarPNRR — KPI Bar Component
 * Barra degli indicatori territoriali e di portafoglio posizionata sotto l'header
 */

export class KPIBar {
  constructor(containerEl, onPulseClick) {
    this.container = containerEl;
    this.onPulseClick = onPulseClick;
    this.kpis = null;
  }

  update(kpis) {
    this.kpis = kpis;
    this.render();
  }

  formatMillions(amount) {
    if (amount >= 1000000) {
      return (amount / 1000000).toLocaleString('it-IT', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' M€';
    } else if (amount >= 1000) {
      return Math.round(amount / 1000).toLocaleString('it-IT') + ' k€';
    }
    return (amount || 0).toLocaleString('it-IT') + ' €';
  }

  render() {
    if (!this.kpis) {
      this.container.innerHTML = '';
      return;
    }

    const {
      totalFunding,
      totalPnrr,
      totalMunicipal,
      totalFoi,
      totalOther,
      totalProjects,
      opereCount,
      paymentPercentage,
      pulse,
      dataQuality
    } = this.kpis;

    const pulseScore = pulse && pulse.score !== null ? pulse.score : '--';
    const pulseLabel = pulse ? pulse.label : 'Dati insufficienti';
    const pulseBadgeClass = pulse ? pulse.badgeClass : 'bg-slate-100 text-slate-700 border-slate-200';

    this.container.innerHTML = `
      <div class="pointer-events-auto flex items-center justify-between gap-1.5 md:gap-2.5 overflow-x-auto scrollbar-none rounded-full bg-white/95 backdrop-blur-md px-3 py-1 md:px-4 md:py-1.5 shadow-card border border-ink/8 text-ink select-none max-w-full">
        
        <!-- 1. Investimenti Totali -->
        <div class="flex items-center gap-1.5 pr-2 md:pr-2.5 border-r border-ink/8 shrink-0">
          <div class="h-6 w-6 rounded-full bg-teal-surface text-teal flex items-center justify-center shrink-0">
            <i class="ph-bold ph-currency-eur text-xs"></i>
          </div>
          <div class="flex flex-col leading-tight">
            <span class="text-[12px] md:text-[13px] font-black tracking-tight text-ink">
              ${this.formatMillions(totalFunding)}
            </span>
            <span class="text-[8.5px] md:text-[9px] font-bold text-ink-muted uppercase tracking-wider">
              Investimenti
            </span>
          </div>
        </div>

        <!-- 2. Risorse PNRR -->
        <div class="flex items-center gap-1.5 pr-2 md:pr-2.5 border-r border-ink/8 shrink-0">
          <div class="h-6 w-6 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
            <i class="ph-bold ph-chart-pie-slice text-xs"></i>
          </div>
          <div class="flex flex-col leading-tight">
            <span class="text-[12px] md:text-[13px] font-black tracking-tight text-blue-700">
              ${this.formatMillions(totalPnrr)}
            </span>
            <span class="text-[8.5px] md:text-[9px] font-bold text-ink-muted uppercase tracking-wider">
              Fondi PNRR
            </span>
          </div>
        </div>

        <!-- 3. Fondi Propri Comunali (+ FOI) -->
        <div class="hidden lg:flex items-center gap-1.5 pr-2 md:pr-2.5 border-r border-ink/8 shrink-0">
          <div class="h-6 w-6 rounded-full bg-emerald-50 text-emerald-700 flex items-center justify-center shrink-0">
            <i class="ph-bold ph-buildings text-xs"></i>
          </div>
          <div class="flex flex-col leading-tight">
            <span class="text-[12px] md:text-[13px] font-black tracking-tight text-emerald-700">
              ${this.formatMillions(totalMunicipal || totalOther)}
            </span>
            <span class="text-[8.5px] md:text-[9px] font-bold text-ink-muted uppercase tracking-wider" title="Cofinanziamento Comune: € ${this.formatMillions(totalMunicipal || 0)} · FOI: € ${this.formatMillions(totalFoi || 0)}">
              Fondi Comune ${totalFoi > 0 ? '+ FOI' : ''}
            </span>
          </div>
        </div>

        <!-- 4. Progetti & Opere -->
        <div class="flex items-center gap-1.5 pr-2 md:pr-2.5 border-r border-ink/8 shrink-0">
          <div class="flex flex-col leading-tight text-left">
            <div class="flex items-baseline gap-1">
              <span class="text-[12px] md:text-[13px] font-black text-ink">${totalProjects}</span>
              <span class="text-[8.5px] font-bold text-ink/60">prog.</span>
            </div>
            <span class="text-[8.5px] md:text-[9px] font-bold text-teal whitespace-nowrap">
              ${opereCount} cantieri
            </span>
          </div>
        </div>

        <!-- 5. % Pagamenti Erogati -->
        <div class="flex items-center gap-1.5 shrink-0">
          <div class="flex flex-col leading-tight">
            <div class="flex items-center gap-1">
              <span class="text-[12px] md:text-[13px] font-black text-emerald-600">
                ${paymentPercentage.toFixed(1)}%
              </span>
              <div class="w-8 md:w-10 h-1.5 rounded-full bg-ink/10 overflow-hidden shrink-0">
                <div class="h-full bg-emerald-500 rounded-full transition-all duration-500" style="width: ${Math.min(100, paymentPercentage)}%;"></div>
              </div>
            </div>
            <span class="text-[8.5px] md:text-[9px] font-bold text-ink-muted uppercase tracking-wider">
              Pagamenti
            </span>
          </div>
        </div>

      </div>
    `;
  }
}
