/**
 * REGGIO PNRR / RadarPNRR — Active Filter Chips Bar
 * Visualizza i filtri attualmente attivi tramite chip removibili
 * e il pulsante "[ Azzera filtri ]".
 */

import { PNRR_MISSIONS, STATUS_LABELS } from '../data/projectsData.js';

export class ActiveFilterChips {
  constructor(containerEl, options = {}) {
    this.container = containerEl;
    this.onRemoveFilter = options.onRemoveFilter;
    this.onResetAll = options.onResetAll;
    this.activeFilters = {};
    this.totalResults = 0;
  }

  update(filters, totalResults) {
    this.activeFilters = filters;
    this.totalResults = totalResults;
    this.render();
  }

  render() {
    const chips = [];
    const f = this.activeFilters;

    // 1. Tipologia: Opere vs Digitale / Servizi
    if (f.type === 'opere' || f.type === 'opera') {
      chips.push({
        key: 'type',
        label: 'Tipologia: Opere & Cantieri',
        icon: 'ph-hammer',
        color: '#0E8C9B'
      });
    } else if (f.type === 'digitale_servizi' || f.type === 'digitale') {
      chips.push({
        key: 'type',
        label: 'Tipologia: Digitale & Servizi',
        icon: 'ph-cpu',
        color: '#0066CC'
      });
    } else if (f.type === 'servizi') {
      chips.push({
        key: 'type',
        label: 'Tipologia: Servizi',
        icon: 'ph-users',
        color: '#0066CC'
      });
    }

    // 3. Missione PNRR
    if (f.mission && f.mission !== 'tutte') {
      const mInfo = PNRR_MISSIONS[f.mission] || { shortName: f.mission, color: '#0E8C9B', icon: 'ph-tag' };
      chips.push({
        key: 'mission',
        label: `${f.mission} · ${mInfo.shortName}`,
        icon: mInfo.icon,
        color: mInfo.color
      });
    }

    // 4. Territorio (Ambito o Quartiere)
    const isAllArea = !f.area || 
      f.area === 'Tutta Reggio Emilia' || 
      f.area === 'Tutti i quartieri' || 
      f.area === 'Tutti gli ambiti' || 
      f.area === 'Tutti gli Ambiti' ||
      f.area === 'Tutti' || 
      f.area === 'tutti' || 
      f.area === 'all';

    if (!isAllArea) {
      chips.push({
        key: 'area',
        label: f.area,
        icon: 'ph-map-pin',
        color: '#0E8C9B'
      });
    }

    // 5. Stato
    if (f.status && f.status !== 'tutti') {
      const stInfo = STATUS_LABELS[f.status] || { label: f.status };
      chips.push({
        key: 'status',
        label: `Stato: ${stInfo.label}`,
        icon: 'ph-clock',
        color: '#132228'
      });
    }

    // 6. Testo Ricerca
    if (f.query && f.query.trim()) {
      chips.push({
        key: 'query',
        label: `Cerca: "${f.query.trim()}"`,
        icon: 'ph-magnifying-glass',
        color: '#5A7079'
      });
    }

    // Se non ci sono filtri attivi, non mostrare la barra
    if (chips.length === 0) {
      this.container.innerHTML = '';
      this.container.classList.add('hidden');
      return;
    }

    this.container.classList.remove('hidden');
    this.container.innerHTML = `
      <div class="flex items-center gap-1.5 flex-wrap rounded-full bg-white/95 backdrop-blur-md px-3 py-1.5 shadow-card border border-teal/30 select-none max-w-full">
        <span class="text-[10px] font-black uppercase tracking-wider text-teal shrink-0 flex items-center gap-1">
          <i class="ph-bold ph-faders"></i>
          <span>Filtri attivi:</span>
        </span>

        <div class="flex items-center gap-1.5 flex-wrap">
          ${chips.map(chip => `
            <span 
              class="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-surface-subtle border border-ink/10 text-ink text-[11px] font-bold transition-all hover:border-teal hover:bg-teal-soft group"
            >
              <span class="h-1.5 w-1.5 rounded-full shrink-0" style="background-color: ${chip.color};"></span>
              <span class="truncate max-w-[180px]">${chip.label}</span>
              <button 
                type="button" 
                class="remove-chip-btn flex h-4 w-4 items-center justify-center rounded-full bg-ink/10 text-ink hover:bg-rose-500 hover:text-white transition-colors ml-0.5"
                data-key="${chip.key}"
                title="Rimuovi questo filtro"
                aria-label="Rimuovi filtro ${chip.label}"
              >
                <i class="ph-bold ph-x text-[9px]"></i>
              </button>
            </span>
          `).join('')}
        </div>

        <!-- Counter & Reset All Button -->
        <div class="flex items-center gap-1.5 ml-auto shrink-0 pl-2 border-l border-ink/10">
          <span class="text-[10px] font-extrabold text-ink-muted">
            ${this.totalResults} ${this.totalResults === 1 ? 'risultato' : 'risultati'}
          </span>
          <button 
            type="button" 
            id="reset-all-filters-btn" 
            class="flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-rose-50 hover:bg-rose-100 text-rose-700 border border-rose-200 text-[10.5px] font-extrabold transition-all active:scale-95"
            title="Azzera tutti i filtri attivi e mostra tutti i progetti"
          >
            <i class="ph-bold ph-trash text-[10px]"></i>
            <span>Azzera filtri</span>
          </button>
        </div>
      </div>
    `;

    // Bind remove clicks
    this.container.querySelectorAll('.remove-chip-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const key = btn.getAttribute('data-key');
        if (this.onRemoveFilter) {
          this.onRemoveFilter(key);
        }
      });
    });

    // Bind reset all click
    const resetAllBtn = this.container.querySelector('#reset-all-filters-btn');
    if (resetAllBtn) {
      resetAllBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (this.onResetAll) {
          this.onResetAll();
        }
      });
    }
  }
}
