/**
 * REGGIO PNRR / RadarPNRR — Analytics Dashboard Overlay ("ANALISI")
 * Visualizza grafici statistici ad alte prestazioni in SVG:
 * 1. Donut Chart: Investimenti per Missione (M1 - M6)
 * 2. Bar Chart: Investimenti per Macro-Tema
 * 3. Horizontal Bar Chart: Top 10 Interventi per importo
 * 4. Donut Chart: Comune di Reggio Emilia vs Altri soggetti attuatori
 * 5. Progress Bars: Stato dei pagamenti per Missione
 * 6. Timeline: Distribuzione temporale delle conclusioni previste
 */

import { PNRR_MISSIONS, MACRO_THEMES } from '../data/projectsData.js';

export class AnalyticsModal {
  constructor(containerEl, projectService, onProjectClick) {
    this.container = containerEl;
    this.projectService = projectService;
    this.onProjectClick = onProjectClick;
  }

  show(projects = this.projectService.allProjects) {
    this.render(projects);
    this.container.classList.remove('hidden');
    document.body.classList.add('overflow-hidden');
  }

  hide() {
    this.container.classList.add('hidden');
    document.body.classList.remove('overflow-hidden');
  }

  formatMillions(amount) {
    if (!amount) return '0 M€';
    if (amount >= 1000000) {
      return (amount / 1000000).toFixed(1) + ' M€';
    }
    return Math.round(amount / 1000) + ' k€';
  }

  render(projects) {
    const kpis = this.projectService.getKPIs(projects);
    const missionsData = this.projectService.getMissionsSummary(projects);
    const themesData = this.projectService.getThemeDistribution(projects);
    const topProjects = this.projectService.getTopInvestments(projects, 10);
    const timelineData = this.projectService.getTimelineDistribution(projects);

    // Prepare Donut for Missions
    const totalFunding = kpis.totalFunding || 1;
    let cumulativePercent = 0;
    const missionSlices = Object.values(missionsData).map(m => {
      const pct = (m.totalFunding / totalFunding) * 100;
      const startPct = cumulativePercent;
      cumulativePercent += pct;
      return {
        ...m,
        pct: pct.toFixed(1),
        startPct,
        endPct: cumulativePercent
      };
    });

    // Helper SVG Donut Path
    function getCoordinatesForPercent(percent) {
      const x = Math.cos(2 * Math.PI * percent);
      const y = Math.sin(2 * Math.PI * percent);
      return [x, y];
    }

    const donutPaths = missionSlices.map(slice => {
      if (slice.totalFunding <= 0) return '';
      const startPctNorm = slice.startPct / 100;
      const endPctNorm = slice.endPct / 100;
      const [startX, startY] = getCoordinatesForPercent(startPctNorm);
      const [endX, endY] = getCoordinatesForPercent(endPctNorm);
      const largeArcFlag = (slice.endPct - slice.startPct) > 50 ? 1 : 0;
      const pathData = `M ${startX} ${startY} A 1 1 0 ${largeArcFlag} 1 ${endX} ${endY} L 0 0`;
      return `<path d="${pathData}" fill="${slice.color}" class="hover:opacity-85 transition-opacity cursor-pointer"><title>${slice.code} - ${slice.name}: ${slice.pct}% (${(slice.totalFunding / 1000000).toFixed(1)} M€)</title></path>`;
    }).join('');

    // Type Breakdown: Opere vs Digitale & Servizi
    let opereFunding = 0;
    let opereCount = 0;
    let digiServiziFunding = 0;
    let digiServiziCount = 0;

    projects.forEach(p => {
      if (p.projectType === 'opera') {
        opereFunding += (p.totalFunding || 0);
        opereCount++;
      } else {
        digiServiziFunding += (p.totalFunding || 0);
        digiServiziCount++;
      }
    });

    const totalTypeFunding = (opereFunding + digiServiziFunding) || 1;
    const operePct = Math.round((opereFunding / totalTypeFunding) * 100);
    const digiPct = 100 - operePct;
    const opEndX = Math.cos(2 * Math.PI * (operePct / 100));
    const opEndY = Math.sin(2 * Math.PI * (operePct / 100));
    const opLargeArc = operePct > 50 ? 1 : 0;

    this.container.innerHTML = `
      <div class="fixed inset-0 z-[100] flex items-center justify-center p-2 sm:p-4 md:p-6 select-none">
        <!-- Backdrop -->
        <div class="modal-backdrop absolute inset-0 bg-ink/60 backdrop-blur-md" id="analytics-backdrop"></div>

        <!-- Dashboard Content Box -->
        <div class="modal-content relative z-10 w-full max-w-5xl max-h-[94dvh] overflow-y-auto rounded-panel bg-white p-5 md:p-7 shadow-float border border-ink/8 text-left custom-scrollbar">
          
          <!-- Top Header -->
          <div class="flex items-center justify-between gap-4 pb-4 border-b border-ink/8">
            <div class="flex items-center gap-3">
              <div class="h-10 w-10 rounded-xl bg-teal text-white flex items-center justify-center font-black shadow-card">
                <i class="ph-bold ph-chart-line-up text-xl"></i>
              </div>
              <div>
                <h2 class="text-xl md:text-2xl font-black text-ink leading-tight">
                  Analisi & Metriche Portafoglio PNRR
                </h2>
                <p class="text-xs font-bold text-teal">
                  Control Room Investimenti · Comune di Reggio Emilia
                </p>
              </div>
            </div>

            <button 
              type="button" 
              id="analytics-close-btn" 
              class="flex h-9 w-9 items-center justify-center rounded-full bg-ink/5 text-ink/60 hover:bg-ink/10 hover:text-ink transition-colors"
              aria-label="Chiudi analytics"
            >
              <i class="ph-bold ph-x text-lg"></i>
            </button>
          </div>

          <!-- Summary KPI Strip: Totale, PNRR, Fondi Propri Comune, FOI -->
          <div class="grid grid-cols-2 sm:grid-cols-4 gap-3 py-4 border-b border-ink/8">
            <div class="p-3 rounded-card bg-surface-subtle border border-ink/6">
              <span class="text-[10px] font-extrabold uppercase tracking-wider text-ink-muted block">Totale Investimenti</span>
              <span class="text-lg md:text-xl font-black text-ink block mt-0.5">${this.formatMillions(kpis.totalFunding)}</span>
            </div>
            <div class="p-3 rounded-card bg-blue-50/50 border border-blue-100">
              <span class="text-[10px] font-extrabold uppercase tracking-wider text-blue-800 block">Fondi PNRR</span>
              <span class="text-lg md:text-xl font-black text-blue-700 block mt-0.5">${this.formatMillions(kpis.totalPnrr)}</span>
            </div>
            <div class="p-3 rounded-card bg-emerald-50/50 border border-emerald-100">
              <span class="text-[10px] font-extrabold uppercase tracking-wider text-emerald-800 block">Fondi Propri Comune</span>
              <span class="text-lg md:text-xl font-black text-emerald-700 block mt-0.5">${this.formatMillions(kpis.totalMunicipal || kpis.totalOther)}</span>
            </div>
            <div class="p-3 rounded-card bg-amber-50/50 border border-amber-100">
              <span class="text-[10px] font-extrabold uppercase tracking-wider text-amber-800 block">FOI (Opere Indiff.)</span>
              <span class="text-lg md:text-xl font-black text-amber-700 block mt-0.5">${this.formatMillions(kpis.totalFoi || 0)}</span>
            </div>
          </div>

          <!-- Charts Grid -->
          <div class="grid grid-cols-1 lg:grid-cols-2 gap-6 py-5">
            
            <!-- 1. Donut Chart: Investimenti per Missione PNRR -->
            <div class="p-4 rounded-card border border-ink/8 bg-surface-subtle/50 flex flex-col justify-between">
              <div>
                <h4 class="text-xs font-black uppercase tracking-wider text-ink mb-1 flex items-center gap-1.5">
                  <i class="ph-bold ph-chart-pie-slice text-teal"></i> Investimenti per Missione PNRR
                </h4>
                <p class="text-[11px] text-ink-muted mb-4">Ripartizione del totale risorse (€ ${this.formatMillions(kpis.totalFunding)})</p>
              </div>

              <div class="flex flex-col sm:flex-row items-center justify-center gap-6">
                <!-- SVG Donut -->
                <div class="relative h-40 w-40 shrink-0">
                  <svg viewBox="-1 -1 2 2" class="h-full w-full -rotate-90">
                    ${donutPaths}
                    <!-- Donut Hole -->
                    <circle cx="0" cy="0" r="0.62" fill="white"></circle>
                  </svg>
                  <div class="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
                    <span class="text-[10px] font-bold text-ink-muted uppercase">Totale</span>
                    <span class="text-[13px] font-black text-ink">${this.formatMillions(kpis.totalFunding)}</span>
                  </div>
                </div>

                <!-- Legend -->
                <div class="space-y-1 text-[11px] min-w-[160px]">
                  ${missionSlices.map(s => `
                    <div class="flex items-center justify-between gap-2">
                      <div class="flex items-center gap-1.5 truncate">
                        <span class="h-2.5 w-2.5 rounded-full shrink-0" style="background-color: ${s.color};"></span>
                        <span class="font-bold text-ink">${s.code}</span>
                        <span class="text-ink-muted truncate">${s.shortName}</span>
                      </div>
                      <span class="font-black text-ink shrink-0">${s.pct}%</span>
                    </div>
                  `).join('')}
                </div>
              </div>
            </div>

            <!-- 2. Donut Chart: Tipologia Intervento (Opere vs Digitale & Servizi) -->
            <div class="p-4 rounded-card border border-ink/8 bg-surface-subtle/50 flex flex-col justify-between">
              <div>
                <h4 class="text-xs font-black uppercase tracking-wider text-ink mb-1 flex items-center gap-1.5">
                  <i class="ph-bold ph-hard-hat text-teal"></i> Tipologia: Opere Pubbliche vs Digitale
                </h4>
                <p class="text-[11px] text-ink-muted mb-4">Ripartizione tra opere fisiche e transizione digitale & servizi del Comune</p>
              </div>

              <div class="flex flex-col sm:flex-row items-center justify-center gap-6">
                <!-- SVG Donut -->
                <div class="relative h-40 w-40 shrink-0">
                  <svg viewBox="-1 -1 2 2" class="h-full w-full -rotate-90">
                    <path d="M 1 0 A 1 1 0 ${opLargeArc} 1 ${opEndX} ${opEndY} L 0 0" fill="#0E8C9B"></path>
                    <path d="M ${opEndX} ${opEndY} A 1 1 0 ${1 - opLargeArc} 1 1 0 L 0 0" fill="#6366F1"></path>
                    <circle cx="0" cy="0" r="0.62" fill="white"></circle>
                  </svg>
                  <div class="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
                    <span class="text-[10px] font-bold text-teal uppercase">Opere</span>
                    <span class="text-[14px] font-black text-teal">${operePct}%</span>
                  </div>
                </div>

                <div class="space-y-3 text-[11.5px] min-w-[180px]">
                  <div class="p-2.5 rounded-card bg-teal-soft/80 border border-teal/20">
                    <div class="flex items-center justify-between">
                      <span class="font-black text-teal flex items-center gap-1.5">
                        <span class="h-2 w-2 rounded-full bg-teal"></span> Opere & Cantieri
                      </span>
                      <span class="font-black text-teal">${operePct}%</span>
                    </div>
                    <div class="flex items-center justify-between text-[10.5px] text-ink-muted mt-1">
                      <span>${opereCount} progetti</span>
                      <span class="font-bold text-ink">${this.formatMillions(opereFunding)}</span>
                    </div>
                  </div>

                  <div class="p-2.5 rounded-card bg-indigo-50/70 border border-indigo-200/60">
                    <div class="flex items-center justify-between">
                      <span class="font-black text-indigo-700 flex items-center gap-1.5">
                        <span class="h-2 w-2 rounded-full bg-indigo-500"></span> Digitale & Servizi
                      </span>
                      <span class="font-black text-indigo-700">${digiPct}%</span>
                    </div>
                    <div class="flex items-center justify-between text-[10.5px] text-ink-muted mt-1">
                      <span>${digiServiziCount} progetti</span>
                      <span class="font-bold text-indigo-900">${this.formatMillions(digiServiziFunding)}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <!-- 3. Bar Chart: Investimenti per Macro-Tema -->
            <div class="p-4 rounded-card border border-ink/8 bg-surface-subtle/50 lg:col-span-2">
              <h4 class="text-xs font-black uppercase tracking-wider text-ink mb-1 flex items-center gap-1.5">
                <i class="ph-bold ph-columns text-teal"></i> Investimenti per Macro-Tema Urbano
              </h4>
              <p class="text-[11px] text-ink-muted mb-4">Volume economico per ambiti di trasformazione della città</p>

              <div class="space-y-2.5">
                ${themesData.map(t => {
                  const pct = totalFunding > 0 ? (t.totalFunding / totalFunding) * 100 : 0;
                  return `
                    <div class="space-y-1">
                      <div class="flex items-center justify-between text-[11.5px] font-bold">
                        <span class="text-ink flex items-center gap-1.5">
                          <i class="ph ${t.icon} text-teal"></i> ${t.label} (${t.count})
                        </span>
                        <span class="text-ink">${this.formatMillions(t.totalFunding)} <span class="text-ink-muted font-normal">(${pct.toFixed(1)}%)</span></span>
                      </div>
                      <div class="w-full h-2 rounded-full bg-ink/10 overflow-hidden">
                        <div class="h-full bg-teal rounded-full" style="width: ${pct}%;"></div>
                      </div>
                    </div>
                  `;
                }).join('')}
              </div>
            </div>

            <!-- 4. Top 10 Interventi per Importo -->
            <div class="p-4 rounded-card border border-ink/8 bg-surface-subtle/50 lg:col-span-2">
              <h4 class="text-xs font-black uppercase tracking-wider text-ink mb-1 flex items-center gap-1.5">
                <i class="ph-bold ph-trophy text-teal"></i> Top 10 Interventi per Valore Economico
              </h4>
              <p class="text-[11px] text-ink-muted mb-4">I principali investimenti strategici in corso o realizzati a Reggio Emilia (clicca per visualizzare la scheda)</p>

              <div class="grid grid-cols-1 md:grid-cols-2 gap-2">
                ${topProjects.map((p, idx) => {
                  const m = PNRR_MISSIONS[p.mission] || PNRR_MISSIONS.M5;
                  return `
                    <button 
                      type="button" 
                      class="top-project-item flex items-center justify-between p-2.5 rounded-card border border-ink/8 bg-white hover:bg-teal-soft hover:border-teal/30 text-left transition-all group"
                      data-cup="${p.cup}"
                    >
                      <div class="flex items-center gap-2.5 min-w-0 flex-1">
                        <span class="h-5 w-5 rounded-full bg-ink/5 text-ink text-[10px] font-black flex items-center justify-center shrink-0">
                          ${idx + 1}
                        </span>
                        <div class="min-w-0 flex-1">
                          <p class="text-[12px] font-bold text-ink leading-tight truncate group-hover:text-teal transition-colors">
                            ${p.title}
                          </p>
                          <div class="flex items-center gap-1.5 text-[10px] text-ink-muted mt-0.5">
                            <span class="font-bold" style="color: ${m.color};">${p.mission}</span>
                            <span>·</span>
                            <span class="truncate">${p.district}</span>
                          </div>
                        </div>
                      </div>
                      <span class="text-[12.5px] font-black text-teal shrink-0 pl-2">
                        ${this.formatMillions(p.totalFunding)}
                      </span>
                    </button>
                  `;
                }).join('')}
              </div>
            </div>

            <!-- 5. Timeline Conclusioni Previste -->
            <div class="p-4 rounded-card border border-ink/8 bg-surface-subtle/50 lg:col-span-2">
              <h4 class="text-xs font-black uppercase tracking-wider text-ink mb-1 flex items-center gap-1.5">
                <i class="ph-bold ph-calendar-blank text-teal"></i> Scadenze e Conclusioni Previste dei Progetti
              </h4>
              <p class="text-[11px] text-ink-muted mb-4">Distribuzione temporale delle date di chiusura dei cantieri e dei collaudi</p>

              <div class="grid grid-cols-2 sm:grid-cols-5 gap-2.5 text-center">
                ${Object.entries(timelineData).map(([yr, count]) => `
                  <div class="p-3 rounded-card bg-white border border-ink/10">
                    <span class="text-xs font-black text-ink-muted block uppercase">${yr}</span>
                    <span class="text-xl font-black text-teal block mt-1">${count}</span>
                    <span class="text-[10px] text-ink-muted block">progetti</span>
                  </div>
                `).join('')}
              </div>
            </div>

          </div>

        </div>
      </div>
    `;

    // Events
    const closeBtn = this.container.querySelector('#analytics-close-btn');
    if (closeBtn) closeBtn.addEventListener('click', () => this.hide());

    const backdrop = this.container.querySelector('#analytics-backdrop');
    if (backdrop) backdrop.addEventListener('click', () => this.hide());

    this.container.querySelectorAll('.top-project-item').forEach(b => {
      b.addEventListener('click', () => {
        const cup = b.getAttribute('data-cup');
        const project = projects.find(p => p.cup === cup);
        if (project && this.onProjectClick) {
          this.hide();
          this.onProjectClick(project);
        }
      });
    });
  }
}
