/**
 * REGGIO PNRR / RadarPNRR — Marker personalizzati per progetti PNRR
 * Marker proporzionali all'investimento economico e codificati per Missione PNRR
 */

import L from 'leaflet';
import { PNRR_MISSIONS } from '../data/projectsData.js';

export function getMarkerSize(totalFunding = 0) {
  if (totalFunding >= 10000000) {
    return { size: 42, iconSize: 20, ringWidth: 4 }; // > 10 M€ (es. Capannone 17, Bus TPL)
  } else if (totalFunding >= 5000000) {
    return { size: 36, iconSize: 18, ringWidth: 3.5 }; // 5 - 10 M€ (es. Dall'Aglio, Casa Comunità)
  } else if (totalFunding >= 2000000) {
    return { size: 32, iconSize: 16, ringWidth: 3 }; // 2 - 5 M€
  } else if (totalFunding >= 1000000) {
    return { size: 28, iconSize: 14, ringWidth: 2.5 }; // 1 - 2 M€
  } else {
    return { size: 24, iconSize: 12, ringWidth: 2 }; // < 1 M€
  }
}

export function createProjectMarker(project, onClick, isActive = false) {
  const missionInfo = PNRR_MISSIONS[project.mission] || PNRR_MISSIONS.M5;
  const { size, iconSize, ringWidth } = getMarkerSize(project.totalFunding);

  const iconName = missionInfo.icon || 'ph-buildings';
  const isComune = project.isComune;

  // Format importo compatto (es. 11.9M€ o 850k€)
  const amountCompact = project.totalFunding >= 1000000
    ? `${(project.totalFunding / 1000000).toFixed(1)}M€`
    : `${Math.round(project.totalFunding / 1000)}k€`;

  const markerHtml = `
    <div 
      class="pnrr-project-marker group relative flex items-center justify-center cursor-pointer select-none transition-transform duration-200 hover:scale-125 ${isActive ? 'scale-125 z-50' : 'z-20'}"
      style="width: ${size}px; height: ${size}px;"
      data-cup="${project.cup}"
      title="${project.title} (${amountCompact})"
    >
      <!-- Pulsing Aura for active or in-progress projects -->
      ${isActive ? `
        <span class="absolute -inset-2 rounded-full animate-ping opacity-60" style="background-color: ${missionInfo.color};"></span>
        <span class="absolute -inset-1.5 rounded-full opacity-40 animate-pulse" style="background-color: ${missionInfo.color};"></span>
      ` : ''}

      <!-- Main Marker Circle -->
      <div 
        class="relative flex items-center justify-center rounded-full shadow-float border-2 border-white text-white font-bold transition-all group-hover:shadow-lg"
        style="
          width: ${size}px; 
          height: ${size}px; 
          background: linear-gradient(135deg, ${missionInfo.color} 0%, ${missionInfo.color}CC 100%);
        "
      >
        <i class="ph-bold ${iconName}" style="font-size: ${iconSize}px;"></i>

        <!-- Mini Comune badge if municipal project -->
        ${isComune ? `
          <span 
            class="absolute -top-1 -right-1 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-white text-teal shadow-sm border border-teal/30"
            title="Soggetto attuatore: Comune di Reggio Emilia"
          >
            <span class="h-1.5 w-1.5 rounded-full bg-teal"></span>
          </span>
        ` : ''}
      </div>

      <!-- Quick Hover Tooltip Label -->
      <div class="pointer-events-none absolute bottom-full left-1/2 -translate-x-1/2 mb-1.5 hidden group-hover:flex flex-col items-center z-50 whitespace-nowrap">
        <div class="rounded-lg bg-ink/95 backdrop-blur-md px-2.5 py-1 text-left shadow-float border border-white/20">
          <p class="text-[10px] font-black text-white leading-tight max-w-[200px] truncate">${project.title}</p>
          <div class="flex items-center gap-2 mt-0.5 text-[9px] text-white/80 font-semibold">
            <span style="color: ${missionInfo.color}; font-weight: 800;">${project.mission}</span>
            <span>·</span>
            <span>${amountCompact}</span>
            <span>·</span>
            <span class="capitalize">${project.status.replace('_', ' ')}</span>
          </div>
        </div>
        <div class="h-1.5 w-1.5 rotate-45 bg-ink/95 -mt-1"></div>
      </div>
    </div>
  `;

  const customIcon = L.divIcon({
    className: 'pnrr-marker-container',
    html: markerHtml,
    iconSize: [size, size],
    iconAnchor: [size / 2, size / 2],
    popupAnchor: [0, -size / 2]
  });

  const marker = L.marker([project.latitude, project.longitude], {
    icon: customIcon,
    riseOnHover: true,
    title: project.title
  });

  if (onClick) {
    marker.on('click', (e) => {
      if (e.originalEvent) e.originalEvent.stopPropagation();
      onClick(project);
    });
  }

  return marker;
}
