/**
 * REGGIO PNRR / RadarPNRR — Left Sidebar Component
 * "Investimenti & Territorio"
 * - Sezione 1: PERIMETRO (Tutta Reggio Emilia + Ambiti A - H e Centro Storico con n. progetti e M€)
 * - Sezione 2: MISSIONI PNRR (M1 - M6 con icona, n. progetti e valore M€)
 * - Sezione 3: LETTURA TERRITORIALE ANALITICA:
 *   Variabili selezionabili:
 *   [ € INVESTITI ] [ PAGAMENTI ] [ N. PROGETTI ] [ AVANZAMENTO ]
 *   Legenda dinamica a classi ricalcolata in tempo reale sui dati filtrati.
 */

import { PNRR_MISSIONS } from '../data/projectsData.js';
import { AMBITI_STRUTTURA } from '../data/reggioEmiliaData.js';

export class LeftSidebar {
  constructor(containerEl, options = {}) {
    this.container = containerEl;
    this.onAreaSelect = options.onAreaSelect;
    this.onMissionSelect = options.onMissionSelect;
    this.onChoroplethMetricChange = options.onChoroplethMetricChange;
    this.onToggleChoropleth = options.onToggleChoropleth;
    this.onBasemapChange = options.onBasemapChange;

    this.isOpen = window.innerWidth >= 1280;
    this.activeArea = null;
    this.activeMission = null;
    this.currentChoroplethMetric = 'funding'; // 'funding' | 'payments' | 'projects' | 'progress'
    this.isChoroplethActive = true;
    this.currentBasemap = 'positron';

    this.ambitiSummary = {};
    this.missionsSummary = {};
    this.choroplethScale = null;

    this.render();
    this.bindEvents();
  }

  updateData(ambitiSummary, missionsSummary, choroplethScale, activeArea, activeMission, currentMetric) {
    this.ambitiSummary = ambitiSummary;
    this.missionsSummary = missionsSummary;
    this.choroplethScale = choroplethScale;
    this.activeArea = activeArea;
    this.activeMission = activeMission;
    if (currentMetric) {
      this.currentChoroplethMetric = currentMetric;
    }
    this.renderContent();
  }

  setActiveArea(area) {
    this.activeArea = area;
    this.renderContent();
  }

  setActiveMission(mission) {
    this.activeMission = mission;
    this.renderContent();
  }

  formatMillions(amount) {
    if (!amount) return '0,0 M€';
    if (amount >= 1000000) {
      return (amount / 1000000).toLocaleString('it-IT', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' M€';
    }
    return Math.round(amount / 1000).toLocaleString('it-IT') + ' k€';
  }

  render() {
    this.container.innerHTML = `
      <div class="relative pointer-events-auto select-none">
        
        <!-- Floating Trigger Pill (Visible when panel is collapsed) -->
        <button 
          type="button" 
          id="left-sidebar-trigger-btn" 
          class="${this.isOpen ? 'hidden' : 'flex'} items-center gap-2 h-10 px-3.5 rounded-full bg-white/95 backdrop-blur-md shadow-card border border-ink/8 text-ink font-bold text-xs hover:bg-teal-soft hover:text-teal hover:border-teal/30 transition-all active:scale-95"
          aria-label="Apri Investimenti e Territorio"
          title="Mostra perimetro, missioni PNRR e densità territoriale"
        >
          <div class="flex items-center gap-1">
            <span class="h-2.5 w-2.5 rounded-full bg-teal"></span>
            <span class="h-2.5 w-2.5 rounded-full bg-[#0066CC]"></span>
            <span class="h-2.5 w-2.5 rounded-full bg-[#10B981]"></span>
          </div>
          <span>Investimenti & Territorio</span>
          <i class="ph-bold ph-caret-down text-xs text-ink/50"></i>
        </button>

        <!-- Expanded Left Sidebar Panel -->
        <div 
          id="left-sidebar-panel" 
          class="${this.isOpen ? 'flex' : 'hidden'} flex-col w-[320px] sm:w-[350px] max-h-[calc(100dvh-185px)] md:max-h-[calc(100dvh-190px)] overflow-y-auto rounded-panel bg-white/98 backdrop-blur-lg p-3.5 shadow-float border border-ink/8 text-left text-xs custom-scrollbar"
        >
          <!-- Dynamic Content Injected Here -->
          <div id="left-sidebar-content"></div>
        </div>

      </div>
    `;

    this.renderContent();
  }

  renderContent() {
    const contentEl = this.container.querySelector('#left-sidebar-content');
    if (!contentEl) return;

    const scale = this.choroplethScale || {
      metricTitle: 'Investimenti PNRR Totali',
      thresholds: [
        { label: '< 1 M€', color: '#A2DFE8' },
        { label: '1 – 5 M€', color: '#5AC8D8' },
        { label: '5 – 10 M€', color: '#2AA5B4' },
        { label: '10 – 20 M€', color: '#0E8C9B' },
        { label: '> 20 M€', color: '#085C66' }
      ]
    };

    contentEl.innerHTML = `
      <!-- Header -->
      <div class="flex items-center justify-between gap-2 pb-3 border-b border-ink/8">
        <div class="flex items-center gap-2">
          <div class="h-7 w-7 rounded-lg bg-teal text-white flex items-center justify-center font-bold shadow-sm">
            <i class="ph-bold ph-buildings text-sm"></i>
          </div>
          <div>
            <h3 class="font-black text-ink text-[14px] leading-tight">Investimenti & Territorio</h3>
            <p class="text-[10px] font-bold text-teal">Comune di Reggio Emilia · Radar PNRR</p>
          </div>
        </div>

        <!-- Minimize Button -->
        <button 
          type="button" 
          id="left-sidebar-close-btn" 
          class="flex h-7 w-7 items-center justify-center rounded-full text-ink/40 hover:bg-ink/5 hover:text-ink transition-colors"
          title="Riduci pannello"
          aria-label="Chiudi pannello"
        >
          <i class="ph-bold ph-caret-up text-sm"></i>
        </button>
      </div>

      <!-- SEZIONE 1: PERIMETRO TERRITORIALE -->
      <div class="py-3 border-b border-ink/8 space-y-2">
        <div class="flex items-center justify-between">
          <span class="text-[10px] font-extrabold uppercase tracking-wider text-teal">
            1. Perimetro Territoriale (Ambiti)
          </span>
          ${this.activeArea ? `
            <button 
              type="button" 
              id="reset-area-btn" 
              class="text-[10px] font-extrabold text-teal hover:underline flex items-center gap-1 cursor-pointer"
            >
              <i class="ph-bold ph-x"></i>
              Azzera filtro (${this.activeArea.replace('Ambito ', 'Amb. ')})
            </button>
          ` : `
            <span class="text-[9.5px] font-bold text-teal flex items-center gap-1">
              <i class="ph-bold ph-check-circle"></i>
              Tutta Reggio Emilia
            </span>
          `}
        </div>

        <!-- Ambiti Grid / Pills -->
        <div class="grid grid-cols-3 gap-1.5 pt-1">
          <button 
            type="button" 
            class="area-select-btn col-span-3 flex items-center justify-between px-3 py-2 rounded-card border transition-all ${
              !this.activeArea || this.activeArea === 'Tutti i quartieri' || this.activeArea === 'Tutta Reggio Emilia' || this.activeArea === 'Tutti gli ambiti'
                ? 'border-teal bg-teal text-white shadow-xs font-black' 
                : 'border-ink/10 bg-white hover:bg-teal-soft hover:border-teal/30 text-ink font-bold'
            }"
            data-area="Tutta Reggio Emilia"
          >
            <div class="flex items-center gap-2">
              <span class="h-2 w-2 rounded-full ${!this.activeArea ? 'bg-white' : 'bg-teal'}"></span>
              <span class="font-black text-[11.5px]">Tutti gli Ambiti</span>
              <span class="text-[10px] ${!this.activeArea ? 'text-white/80' : 'text-ink-muted'}">(Tutta la città)</span>
            </div>
            <div class="flex items-center gap-1.5">
              ${!this.activeArea ? '<span class="text-[9px] uppercase font-black tracking-wider bg-white/20 px-1.5 py-0.5 rounded">Attivo</span>' : ''}
              <span class="text-[10.5px] font-extrabold ${!this.activeArea ? 'text-white' : 'text-teal'}">${this.formatMillions(Object.values(this.ambitiSummary).reduce((acc, curr) => acc + (curr.totalFunding || 0), 0))}</span>
            </div>
          </button>

          ${AMBITI_STRUTTURA.map(a => {
            const isSelected = this.activeArea === a.name;
            const data = this.ambitiSummary[a.name] || { count: 0, totalFunding: 0 };
            return `
              <button 
                type="button" 
                class="area-select-btn flex flex-col items-start p-1.5 rounded-card border text-left transition-all ${
                  isSelected 
                    ? 'border-teal bg-teal-soft text-teal ring-2 ring-teal font-black shadow-xs' 
                    : 'border-ink/8 bg-white hover:bg-surface-hover text-ink'
                }"
                data-area="${a.name}"
                title="${a.name} (${a.lettera})"
              >
                <div class="flex items-center justify-between w-full">
                  <span class="inline-flex h-4 w-4 rounded-full text-[9px] font-black items-center justify-center transition-colors ${
                    isSelected 
                      ? 'bg-teal text-white shadow-xs' 
                      : 'bg-ink/10 text-ink/70'
                  }">
                    ${a.lettera}
                  </span>
                  <span class="text-[9px] font-bold ${isSelected ? 'text-teal font-black' : 'text-ink-muted'}">${data.count} p.</span>
                </div>
                <span class="text-[10px] truncate w-full mt-1 ${isSelected ? 'font-black text-teal' : 'font-bold text-ink'}">${a.name.replace('Ambito ', 'Amb. ')}</span>
                <span class="text-[9px] ${isSelected ? 'font-black text-teal' : 'font-bold text-ink/65'}">${this.formatMillions(data.totalFunding)}</span>
              </button>
            `;
          }).join('')}
        </div>
      </div>

      <!-- SEZIONE 2: MISSIONI PNRR -->
      <div class="py-3 border-b border-ink/8 space-y-2">
        <div class="flex items-center justify-between">
          <span class="text-[10px] font-extrabold uppercase tracking-wider text-teal">
            2. Missioni PNRR
          </span>
          ${this.activeMission ? `
            <button 
              type="button" 
              id="reset-mission-btn" 
              class="text-[10px] font-extrabold text-teal hover:underline"
            >
              Azzera filtro (${this.activeMission})
            </button>
          ` : '<span class="text-[9px] text-ink-muted">Tutte le 6 missioni</span>'}
        </div>

        <div class="space-y-1.5 pt-0.5">
          ${Object.values(PNRR_MISSIONS).map(m => {
            const isSelected = this.activeMission === m.code;
            const data = this.missionsSummary[m.code] || { count: 0, totalFunding: 0, payments: 0, paymentPercentage: 0 };
            return `
              <button 
                type="button" 
                class="mission-select-btn group flex items-center justify-between w-full p-2 rounded-card border transition-all text-left ${isSelected ? 'border-teal bg-teal-soft ring-1 ring-teal' : 'border-ink/8 bg-white hover:bg-surface-hover'}"
                data-mission="${m.code}"
              >
                <div class="flex items-center gap-2 min-w-0 flex-1">
                  <div class="h-6 w-6 rounded-md flex items-center justify-center shrink-0 shadow-xs" style="background-color: ${m.lightColor}; color: ${m.color};">
                    <i class="ph-bold ${m.icon} text-xs"></i>
                  </div>
                  <div class="min-w-0 flex-1 leading-tight">
                    <div class="flex items-center gap-1.5">
                      <span class="text-[11px] font-black text-ink">${m.code}</span>
                      <span class="text-[11px] font-semibold text-ink/80 truncate">${m.shortName}</span>
                    </div>
                    <div class="flex items-center gap-1.5 text-[9px] text-ink-muted mt-0.5">
                      <span>${data.count} ${data.count === 1 ? 'progetto' : 'progetti'}</span>
                      <span>·</span>
                      <span class="font-bold text-emerald-600">${data.paymentPercentage}% pagato</span>
                    </div>
                  </div>
                </div>

                <div class="text-right shrink-0 pl-2">
                  <span class="text-[11px] font-black text-ink" style="color: ${m.color};">
                    ${this.formatMillions(data.totalFunding)}
                  </span>
                </div>
              </button>
            `;
          }).join('')}
        </div>
      </div>

      <!-- SEZIONE 3: LETTURA TERRITORIALE ANALITICA (DENSITÀ AMBITI) -->
      <div class="py-3 border-b border-ink/8 space-y-2.5">
        <div class="flex items-center justify-between">
          <span class="text-[10px] font-extrabold uppercase tracking-wider text-teal">
            3. Variabile Choropleth Territoriale
          </span>
          <!-- Switch Choropleth -->
          <label class="relative inline-flex items-center cursor-pointer shrink-0">
            <input type="checkbox" id="switch-choropleth" class="sr-only peer" ${this.isChoroplethActive ? 'checked' : ''} />
            <div class="w-8 h-4.5 bg-ink/20 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-ink/10 after:border after:rounded-full after:h-3.5 after:w-3.5 after:transition-all peer-checked:bg-teal"></div>
          </label>
        </div>

        <p class="text-[11px] text-ink/80 leading-relaxed">
          Seleziona la grandezza analitica da mappare sugli Ambiti. Scala e legenda si ricalcolano automaticamente sui dati filtrati:
        </p>

        <!-- Indicatore Selettore Coropletica 4 Variabili Richieste -->
        <div class="grid grid-cols-2 gap-1.5 pt-0.5">
          <button 
            type="button" 
            class="metric-btn px-2 py-1.5 rounded-lg border text-[10.5px] font-black transition-all ${this.currentChoroplethMetric === 'funding' ? 'bg-teal text-white border-teal shadow-xs' : 'bg-surface-subtle border-ink/8 text-ink hover:bg-teal-soft'}"
            data-metric="funding"
          >
            € INVESTITI
          </button>
          <button 
            type="button" 
            class="metric-btn px-2 py-1.5 rounded-lg border text-[10.5px] font-black transition-all ${this.currentChoroplethMetric === 'payments' ? 'bg-teal text-white border-teal shadow-xs' : 'bg-surface-subtle border-ink/8 text-ink hover:bg-teal-soft'}"
            data-metric="payments"
          >
            PAGAMENTI
          </button>
          <button 
            type="button" 
            class="metric-btn px-2 py-1.5 rounded-lg border text-[10.5px] font-black transition-all ${this.currentChoroplethMetric === 'projects' ? 'bg-teal text-white border-teal shadow-xs' : 'bg-surface-subtle border-ink/8 text-ink hover:bg-teal-soft'}"
            data-metric="projects"
          >
            N. PROGETTI
          </button>
          <button 
            type="button" 
            class="metric-btn px-2 py-1.5 rounded-lg border text-[10.5px] font-black transition-all ${this.currentChoroplethMetric === 'progress' ? 'bg-teal text-white border-teal shadow-xs' : 'bg-surface-subtle border-ink/8 text-ink hover:bg-teal-soft'}"
            data-metric="progress"
          >
            AVANZAMENTO
          </button>
        </div>

        <!-- Dynamic Gradient Scale -->
        <div class="space-y-1.5 pt-1.5">
          <div class="flex items-center justify-between text-[9.5px] font-black uppercase text-teal">
            <span>Scala: ${scale.metricTitle}</span>
          </div>
          
          <div class="grid grid-cols-5 h-3 rounded-full overflow-hidden border border-ink/10 shadow-inner">
            ${scale.thresholds.map(t => `
              <div style="background-color: ${t.color};" title="${t.label}"></div>
            `).join('')}
          </div>

          <div class="flex items-center justify-between text-[8.5px] font-bold text-ink/75 px-0.5">
            ${scale.thresholds.map(t => `
              <span class="truncate">${t.label}</span>
            `).join('')}
          </div>
        </div>
      </div>

      <!-- SEZIONE 4: STILE MAPPA (BASEMAP) -->
      <div class="pt-3 space-y-2">
        <span class="text-[10px] font-extrabold uppercase tracking-wider text-teal block">
          4. Stile Cartografico CARTO
        </span>

        <div class="grid grid-cols-4 gap-1.5">
          <button 
            type="button" 
            class="basemap-btn px-2 py-1.5 rounded-lg border text-[10px] font-bold transition-all ${this.currentBasemap === 'positron' ? 'border-teal bg-teal-soft text-teal font-black shadow-xs' : 'border-ink/8 bg-surface-subtle text-ink hover:bg-surface-hover'}"
            data-basemap="positron"
          >
            Positron
          </button>
          <button 
            type="button" 
            class="basemap-btn px-2 py-1.5 rounded-lg border text-[10px] font-bold transition-all ${this.currentBasemap === 'voyager' ? 'border-teal bg-teal-soft text-teal font-black shadow-xs' : 'border-ink/8 bg-surface-subtle text-ink hover:bg-surface-hover'}"
            data-basemap="voyager"
          >
            Voyager
          </button>
          <button 
            type="button" 
            class="basemap-btn px-2 py-1.5 rounded-lg border text-[10px] font-bold transition-all ${this.currentBasemap === 'dark' ? 'border-teal bg-teal-soft text-teal font-black shadow-xs' : 'border-ink/8 bg-surface-subtle text-ink hover:bg-surface-hover'}"
            data-basemap="dark"
          >
            Dark
          </button>
          <button 
            type="button" 
            class="basemap-btn px-2 py-1.5 rounded-lg border text-[10px] font-bold transition-all ${this.currentBasemap === 'satellite' ? 'border-teal bg-teal-soft text-teal font-black shadow-xs' : 'border-ink/8 bg-surface-subtle text-ink hover:bg-surface-hover'}"
            data-basemap="satellite"
          >
            Satellite
          </button>
        </div>
      </div>

      <!-- SEZIONE 5: FONTI DATI & AGGIORNAMENTO -->
      <div class="pt-3 mt-1 border-t border-ink/8 text-[11px] space-y-1.5">
        <div class="flex items-center justify-between">
          <span class="text-[10px] font-extrabold uppercase tracking-wider text-teal flex items-center gap-1">
            <i class="ph-bold ph-database"></i> Fonti dei Dati
          </span>
          <span class="text-[9.5px] font-black text-emerald-700 bg-emerald-50 border border-emerald-200 px-1.5 py-0.5 rounded-full">
            Aggiornato: Sett. 2024
          </span>
        </div>
        <p class="text-[10.5px] text-ink-muted leading-tight">
          Dati ufficiali: Italia Domani (MEF ReGiS), OpenPNRR (Openpolis) e SIT Comune di Reggio Emilia.
        </p>
      </div>
    `;

    this.bindEventsInternal();
  }

  bindEvents() {
    this.container.addEventListener('click', (e) => {
      const triggerBtn = e.target.closest('#left-sidebar-trigger-btn');
      if (triggerBtn) {
        this.isOpen = true;
        this.updateVisibility();
      }

      const closeBtn = e.target.closest('#left-sidebar-close-btn');
      if (closeBtn) {
        this.isOpen = false;
        this.updateVisibility();
      }
    });
  }

  bindEventsInternal() {
    const panel = this.container.querySelector('#left-sidebar-panel');
    if (!panel) return;

    // Ambito select clicks (Toggle)
    panel.querySelectorAll('.area-select-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const area = btn.getAttribute('data-area');
        const isAll = !area || 
          area === 'Tutta Reggio Emilia' || 
          area === 'Tutti i quartieri' || 
          area === 'Tutti gli ambiti' || 
          area === 'Tutti gli Ambiti' ||
          area === 'Tutti' || 
          area === 'tutti' || 
          area === 'all';

        if (isAll) {
          if (this.onAreaSelect) this.onAreaSelect(null);
        } else {
          const next = this.activeArea === area ? null : area;
          if (this.onAreaSelect) this.onAreaSelect(next);
        }
      });
    });

    const resetAreaBtn = panel.querySelector('#reset-area-btn');
    if (resetAreaBtn) {
      resetAreaBtn.addEventListener('click', () => {
        if (this.onAreaSelect) this.onAreaSelect(null);
      });
    }

    // Mission clicks (Toggle)
    panel.querySelectorAll('.mission-select-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const mission = btn.getAttribute('data-mission');
        const next = this.activeMission === mission ? null : mission;
        if (this.onMissionSelect) {
          this.onMissionSelect(next);
        }
      });
    });

    const resetMissionBtn = panel.querySelector('#reset-mission-btn');
    if (resetMissionBtn) {
      resetMissionBtn.addEventListener('click', () => {
        if (this.onMissionSelect) this.onMissionSelect(null);
      });
    }

    // Choropleth Switch
    const switchChoropleth = panel.querySelector('#switch-choropleth');
    if (switchChoropleth) {
      switchChoropleth.addEventListener('change', (e) => {
        this.isChoroplethActive = e.target.checked;
        if (this.onToggleChoropleth) {
          this.onToggleChoropleth(this.isChoroplethActive);
        }
      });
    }

    // Metric Switchers (4 variabili: funding, payments, projects, progress)
    panel.querySelectorAll('.metric-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const metric = btn.getAttribute('data-metric');
        this.currentChoroplethMetric = metric;
        if (this.onChoroplethMetricChange) {
          this.onChoroplethMetricChange(metric);
        }
      });
    });

    // Basemaps Switchers
    panel.querySelectorAll('.basemap-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const bm = btn.getAttribute('data-basemap');
        this.currentBasemap = bm;
        if (this.onBasemapChange) {
          this.onBasemapChange(bm);
        }
        this.renderContent();
      });
    });
  }

  updateVisibility() {
    const trigger = this.container.querySelector('#left-sidebar-trigger-btn');
    const panel = this.container.querySelector('#left-sidebar-panel');
    if (trigger && panel) {
      if (this.isOpen) {
        trigger.classList.add('hidden');
        panel.classList.remove('hidden');
        panel.classList.add('flex');
      } else {
        trigger.classList.remove('hidden');
        panel.classList.remove('flex');
        panel.classList.add('hidden');
      }
    }
  }
}
