/**
 * REGGIO PNRR / RadarPNRR — Scheda Dettaglio Progetto Modal / Drawer
 * Presenta tutti i livelli informativi: finanziari, procedurali, identificativi,
 * governance, localizzazione territoriale con centratura mappa, cronoprogramma e fonti.
 */

import { PNRR_MISSIONS, STATUS_LABELS } from '../data/projectsData.js';
import { calculateProjectDataQuality } from '../services/etlService.js';

export class ProjectDetailModal {
  constructor(containerEl, options = {}) {
    this.container = containerEl;
    this.onClose = options.onClose;
    this.onCenterOnMap = options.onCenterOnMap;
    this.currentProject = null;

    this.bindGlobalEvents();
  }

  show(project) {
    this.currentProject = project;
    this.render();
    this.container.classList.remove('hidden');
    document.body.classList.add('overflow-hidden');
  }

  hide() {
    this.container.classList.add('hidden');
    document.body.classList.remove('overflow-hidden');
    if (this.onClose) {
      this.onClose();
    }
  }

  formatCurrency(val) {
    if (val === null || val === undefined) return 'Non disponibile';
    return '€ ' + Number(val).toLocaleString('it-IT', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
  }

  formatMillions(amount) {
    if (!amount) return '0 M€';
    if (amount >= 1000000) {
      return (amount / 1000000).toLocaleString('it-IT', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' M€';
    }
    return Math.round(amount / 1000).toLocaleString('it-IT') + ' k€';
  }

  formatDate(dateStr) {
    if (!dateStr) return 'Da definire';
    const [year, month, day] = dateStr.split('-');
    if (!day || !month || !year) return dateStr;
    return `${day}/${month}/${year}`;
  }

  render() {
    if (!this.currentProject) return;
    const p = this.currentProject;
    const m = PNRR_MISSIONS[p.mission] || PNRR_MISSIONS.M5;
    const st = STATUS_LABELS[p.status] || STATUS_LABELS.in_corso;
    const dq = calculateProjectDataQuality(p);

    const residual = Math.max(0, (p.totalFunding || 0) - (p.payments || 0));
    const payPct = p.totalFunding > 0 ? ((p.payments || 0) / p.totalFunding) * 100 : 0;

    this.container.innerHTML = `
      <div class="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-4">
        <!-- Backdrop -->
        <div class="modal-backdrop absolute inset-0 bg-ink/50 backdrop-blur-sm" id="detail-backdrop"></div>

        <!-- Modal Card Content -->
        <div class="modal-content relative z-10 w-full max-w-2xl max-h-[92dvh] overflow-y-auto rounded-t-panel md:rounded-panel bg-white p-5 md:p-6 shadow-float border border-ink/8 text-left custom-scrollbar">
          
          <!-- Top Bar: Mission, Status, Close -->
          <div class="flex items-start justify-between gap-4 pb-3 border-b border-ink/8">
            <div class="min-w-0 flex-1">
              <div class="flex flex-wrap items-center gap-2 mb-2">
                <!-- Mission Badge -->
                <span 
                  class="inline-flex items-center gap-1.5 text-[11px] font-black uppercase px-2.5 py-1 rounded-md"
                  style="background-color: ${m.lightColor}; color: ${m.color};"
                >
                  <i class="ph-bold ${m.icon} text-xs"></i>
                  <span>${p.mission} · ${m.name}</span>
                </span>

                <!-- Status Badge -->
                <span class="inline-flex items-center text-[10px] font-extrabold uppercase px-2 py-0.5 rounded border ${st.badgeClass}">
                  ${st.label}
                </span>

                <!-- Ministero di Riferimento Badge -->
                <span class="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded border border-amber-200/80 bg-amber-50 text-amber-900 truncate max-w-[280px]" title="${p.ministry || p.ownerAdministration}">
                  <i class="ph-bold ph-landmark text-amber-700"></i>
                  <span class="truncate">${p.ministry || p.ownerAdministration}</span>
                </span>

                <!-- Data Quality Badge -->
                <span class="inline-flex items-center gap-1 text-[10px] font-bold text-slate-600 bg-slate-100 px-2 py-0.5 rounded-full" title="Completezza record amministrativo: ${dq.score}%">
                  <i class="ph-bold ph-shield-check text-emerald-600"></i>
                  <span>Dato: ${dq.score}%</span>
                </span>
              </div>

              <!-- Project Title -->
              <h2 class="text-lg md:text-xl font-black text-ink leading-snug">
                ${p.title}
              </h2>

              <!-- RUP Chip -->
              <div class="mt-1.5 flex flex-wrap items-center gap-2">
                <span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-teal/10 border border-teal/20 text-[11.5px] font-extrabold text-teal-dark">
                  <i class="ph-bold ph-user-circle text-teal text-sm"></i>
                  <span>RUP: <strong>${p.rup || 'Non specificato'}</strong></span>
                </span>
                ${p.measure ? `
                  <span class="text-[11px] text-ink-muted font-medium">
                    <i class="ph ph-tag text-xs text-teal"></i> ${p.measure}
                  </span>
                ` : ''}
              </div>

              <!-- Component and Measure -->
              <p class="text-[12px] text-ink-muted mt-1 leading-normal font-medium">
                ${p.component}
              </p>
            </div>

            <!-- Close Button -->
            <button 
              type="button" 
              id="detail-close-btn" 
              class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-ink/5 text-ink/60 hover:bg-ink/10 hover:text-ink transition-colors"
              aria-label="Chiudi scheda"
            >
              <i class="ph-bold ph-x text-lg"></i>
            </button>
          </div>

          <!-- Financial Breakdown Card (Quadro Economico Ufficiale: IMPORTO TOTALE | FONDI PROPRI COMUNALI | FONDI PNRR | FOI) -->
          <div class="my-4 p-3.5 sm:p-4 rounded-card bg-surface-subtle border border-ink/8">
            <div class="flex items-center justify-between gap-2 mb-2.5">
              <span class="text-[10.5px] font-black uppercase tracking-wider text-ink flex items-center gap-1.5">
                <i class="ph-bold ph-coins text-teal"></i> Quadro Economico dell'Intervento
              </span>
              <span class="text-[9.5px] font-extrabold text-teal bg-teal-soft/80 border border-teal/20 px-2 py-0.5 rounded-full">
                ${p.isComune ? 'Comune di Reggio Emilia' : 'Soggetto Attuatore Esterno'}
              </span>
            </div>

            <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-left">
              <!-- 1. IMPORTO TOTALE -->
              <div class="p-2.5 rounded-card bg-white border border-ink/8 shadow-2xs">
                <span class="text-[9px] font-black uppercase tracking-wider text-ink-muted block">Importo Totale</span>
                <span class="text-[13px] sm:text-[14.5px] font-black text-ink block mt-0.5">€ ${this.formatCurrency(p.totalFunding)}</span>
              </div>

              <!-- 2. FONDI PROPRI COMUNALI -->
              <div class="p-2.5 rounded-card bg-white border border-emerald-200/80 bg-emerald-50/20 shadow-2xs">
                <span class="text-[9px] font-black uppercase tracking-wider text-emerald-800 block">Fondi Propri Comunali</span>
                <span class="text-[13px] sm:text-[14.5px] font-black text-emerald-700 block mt-0.5">€ ${this.formatCurrency(p.municipalFunding ?? (p.isComune ? p.otherFunding : 0))}</span>
                ${p.totalFunding > 0 && (p.municipalFunding || 0) > 0 ? `<span class="text-[8.5px] font-bold text-emerald-600 block leading-tight mt-0.5">${((p.municipalFunding / p.totalFunding) * 100).toFixed(1)}% cofinanziamento</span>` : ''}
              </div>

              <!-- 3. FONDI PNRR -->
              <div class="p-2.5 rounded-card bg-white border border-teal/30 bg-teal-soft/30 shadow-2xs">
                <span class="text-[9px] font-black uppercase tracking-wider text-teal-800 block">Fondi PNRR</span>
                <span class="text-[13px] sm:text-[14.5px] font-black text-teal-dark block mt-0.5">€ ${this.formatCurrency(p.pnrrFunding)}</span>
                ${p.totalFunding > 0 && (p.pnrrFunding || 0) > 0 ? `<span class="text-[8.5px] font-bold text-teal block leading-tight mt-0.5">${((p.pnrrFunding / p.totalFunding) * 100).toFixed(1)}% quota PNRR</span>` : ''}
              </div>

              <!-- 4. FOI -->
              <div class="p-2.5 rounded-card bg-white border border-amber-200/80 bg-amber-50/20 shadow-2xs">
                <span class="text-[9px] font-black uppercase tracking-wider text-amber-800 block">FOI (Opere Indiff.)</span>
                <span class="text-[13px] sm:text-[14.5px] font-black text-amber-700 block mt-0.5">€ ${this.formatCurrency(p.foiFunding || 0)}</span>
                ${(p.foiFunding || 0) > 0 ? `<span class="text-[8.5px] font-bold text-amber-600 block leading-tight mt-0.5">adeguamento prezzi</span>` : ''}
              </div>
            </div>

            <!-- Financial Progress Bar -->
            <div class="mt-3 pt-3 border-t border-ink/8">
              <div class="flex items-center justify-between text-[11px] mb-1 font-bold">
                <span class="text-ink-muted">Avanzamento Spesa (Pagamenti Erogati)</span>
                <span class="text-emerald-700 font-black">${payPct.toFixed(1)}%</span>
              </div>
              <div class="w-full h-2 rounded-full bg-ink/10 overflow-hidden">
                <div class="h-full bg-emerald-500 rounded-full" style="width: ${Math.min(100, payPct)}%;"></div>
              </div>
              <div class="flex items-center justify-between text-[10px] text-ink-muted mt-1.5">
                <span>Residuo da liquidare: € ${this.formatCurrency(residual)}</span>
                <span class="font-bold text-ink">Ministero: ${p.ministry || p.ownerAdministration}</span>
              </div>
            </div>
          </div>

          <!-- Description -->
          <div class="py-2">
            <h4 class="text-[11px] font-black uppercase tracking-wider text-teal mb-1.5 flex items-center gap-1.5">
              <i class="ph-bold ph-info"></i> Descrizione dell'Intervento
            </h4>
            <p class="text-[13px] text-ink/90 leading-relaxed font-normal">
              ${p.description || 'Nessuna descrizione dettagliata disponibile.'}
            </p>
          </div>

          <!-- Identificatori e CUP -->
          <div class="py-3 border-t border-b border-ink/8 my-2">
            <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-left font-mono text-[11px]">
              <div class="p-2 rounded-card bg-surface-subtle">
                <span class="text-[9px] font-sans font-bold text-ink-muted uppercase block">CUP</span>
                <span class="font-black text-teal select-all">${p.cup}</span>
              </div>
              <div class="p-2 rounded-card bg-surface-subtle">
                <span class="text-[9px] font-sans font-bold text-ink-muted uppercase block">RUP</span>
                <span class="font-sans font-black text-ink truncate block" title="${p.rup}">
                  ${p.rup || 'N.D.'}
                </span>
              </div>
              <div class="p-2 rounded-card bg-surface-subtle">
                <span class="text-[9px] font-sans font-bold text-ink-muted uppercase block">CLP (Locale)</span>
                <span class="font-bold text-ink select-all">${p.clp || 'N.D.'}</span>
              </div>
              <div class="p-2 rounded-card bg-surface-subtle">
                <span class="text-[9px] font-sans font-bold text-ink-muted uppercase block">Soggetto Attuatore</span>
                <span class="font-sans font-bold text-ink truncate block" title="${p.implementingBody}">
                  ${p.implementingBody}
                </span>
              </div>
            </div>
          </div>

          <!-- Territorial Localisation -->
          <div class="py-2">
            <h4 class="text-[11px] font-black uppercase tracking-wider text-teal mb-1.5 flex items-center gap-1.5">
              <i class="ph-bold ph-map-pin"></i> Localizzazione & Quartiere
            </h4>
            <div class="grid grid-cols-3 gap-2 text-left text-[12px] p-2.5 rounded-card bg-surface-subtle">
              <div>
                <span class="text-[10px] font-bold text-ink-muted uppercase block">Indirizzo</span>
                <span class="font-bold text-ink">${p.address || 'Territorio comunale'}</span>
              </div>
              <div>
                <span class="text-[10px] font-bold text-ink-muted uppercase block">Quartiere</span>
                <span class="font-black text-teal">${p.district}</span>
              </div>
              <div>
                <span class="text-[10px] font-bold text-ink-muted uppercase block">Ambito Territoriale</span>
                <span class="font-bold text-ink">${p.area}</span>
              </div>
            </div>
            ${p.latitude && p.longitude ? `
              <button 
                type="button" 
                id="center-on-map-btn" 
                class="w-full mt-3 flex items-center justify-center gap-2 px-4 py-2 rounded-card bg-teal text-white hover:bg-teal-dark text-[12px] font-black transition-all shadow-xs active:scale-95"
              >
                <i class="ph-bold ph-crosshair"></i>
                <span>Centra il progetto sulla mappa</span>
              </button>
            ` : ''}
          </div>

          <!-- CRONOPROGRAMMA & STATO FISICO -->
          <div class="py-3 border-b border-ink/8">
            <h4 class="text-[11px] font-black uppercase tracking-wider text-teal mb-2.5 flex items-center gap-1.5">
              <i class="ph-bold ph-calendar-check"></i> Cronoprogramma & Avanzamento
            </h4>

            <div class="grid grid-cols-3 gap-2 text-center mb-3">
              <div class="p-2 rounded-card bg-surface-subtle">
                <span class="text-[9.5px] font-bold text-ink-muted uppercase block">Data Avvio</span>
                <span class="text-[12px] font-bold text-ink block mt-0.5">${this.formatDate(p.startDate)}</span>
              </div>
              <div class="p-2 rounded-card bg-surface-subtle">
                <span class="text-[9.5px] font-bold text-ink-muted uppercase block">Fine Prevista</span>
                <span class="text-[12px] font-bold text-ink block mt-0.5">${this.formatDate(p.expectedEndDate)}</span>
              </div>
              <div class="p-2 rounded-card bg-surface-subtle">
                <span class="text-[9.5px] font-bold text-ink-muted uppercase block">Avanzamento Stimato</span>
                <span class="text-[12px] font-black text-teal block mt-0.5">${p.progress}%</span>
              </div>
            </div>

            <!-- Physical Progress Bar -->
            <div class="w-full h-2 rounded-full bg-ink/10 overflow-hidden">
              <div class="h-full bg-teal rounded-full" style="width: ${p.progress}%;"></div>
            </div>
          </div>

          <!-- FONTI E DATA QUALITY -->
          <div class="pt-3 border-t border-ink/8 text-[11px] space-y-2">
            <div class="flex items-start justify-between gap-2">
              <span class="font-bold text-ink flex items-center gap-1 shrink-0">
                <i class="ph-bold ph-database text-teal"></i> Fonti Dati:
              </span>
              <span class="text-right text-ink/85 font-medium">
                ${p.sources ? `${p.sources.financial} · ${p.sources.location}` : 'Italia Domani (ReGiS) · OpenPNRR · SIT Comune RE'}
              </span>
            </div>
            <div class="flex items-center justify-between gap-2">
              <span class="font-bold text-ink-muted flex items-center gap-1">
                <i class="ph-bold ph-calendar-check text-teal"></i> Riferimento Aggiornamento Fonti:
              </span>
              <span class="px-2.5 py-0.5 rounded-full bg-emerald-50 border border-emerald-200 text-emerald-800 text-[10.5px] font-black text-right">
                ${p.sourceUpdateDate || '13 Giugno 2026 (ReGiS v13.0) · 26 Febbraio 2026 (OpenPNRR)'}
              </span>
            </div>
          </div>

        </div>
      </div>
    `;

    // Bind inside elements
    const closeBtn = this.container.querySelector('#detail-close-btn');
    if (closeBtn) closeBtn.addEventListener('click', () => this.hide());

    const backdrop = this.container.querySelector('#detail-backdrop');
    if (backdrop) backdrop.addEventListener('click', () => this.hide());

    const centerBtn = this.container.querySelector('#center-on-map-btn');
    if (centerBtn) {
      centerBtn.addEventListener('click', () => {
        if (this.onCenterOnMap && p.latitude && p.longitude) {
          this.onCenterOnMap(p);
          this.hide();
        }
      });
    }
  }

  bindGlobalEvents() {
    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && !this.container.classList.contains('hidden')) {
        this.hide();
      }
    });
  }
}
