/**
 * REGGIO PNRR / RadarPNRR — Interactive WebGIS Map Component
 * - Full-screen Leaflet Map con tessere CARTO (Positron chiaro, Voyager, Dark, Satellite)
 * - Layer Marker PNRR: icone tematiche colorate per Missione PNRR (M1 - M6) e proporzionali all'investimento
 * - Layer Coropletico Analitico Dinamico per Ambito Territoriale e Quartieri:
 *   Aggiornamento immediato al cambio di variabile (€ Investiti, Pagamenti, N. Progetti, Avanzamento)
 *   e al passaggio del mouse mostra:
 *     AMBITO E
 *     14 progetti
 *     € 18,4 M investiti
 *     € 11,2 M PNRR
 *     € 6,1 M pagati
 *     54% avanzamento medio
 */

import L from 'leaflet';
import { createProjectMarker } from './markers.js';
import { QUARTIERI_GEOJSON, AMBITI_CENTROIDS } from '../data/quartieriGeoJSON.js';

export const CARTO_API_KEY = 'cb1_31to_1_1eadc9b8a5e5f1d150060d5d';

export class RadarPnrrMap {
  constructor(containerId, options = {}) {
    this.containerId = containerId;
    this.onProjectSelect = options.onProjectSelect;
    this.onQuartiereSelect = options.onQuartiereSelect;
    this.onAmbitoSelect = options.onAmbitoSelect;

    this.map = null;
    this.markersLayer = L.layerGroup();
    this.quartieriLayer = null;
    this.ambitiLettersLayer = L.layerGroup();
    this.userLocationMarker = null;
    this.userAccuracyCircle = null;
    this.searchMarker = null;

    this.currentActiveCup = null;
    this.selectedArea = null;
    this.projects = [];
    this.ambitiData = {};
    this.choroplethScale = null;
    this.isChoroplethVisible = true;

    // Centro geografico di Reggio Emilia
    this.defaultCenter = [44.6983, 10.6308];
    this.defaultZoom = window.innerWidth < 768 ? 13 : 13.5;

    this.initMap();
  }

  initMap() {
    this.map = L.map(this.containerId, {
      center: this.defaultCenter,
      zoom: this.defaultZoom,
      zoomControl: false,
      attributionControl: true
    });

    // Custom Zoom control in basso a destra
    L.control.zoom({
      position: 'bottomright'
    }).addTo(this.map);

    // Tessere Cartografiche CARTO
    const keyParam = CARTO_API_KEY ? `?key=${CARTO_API_KEY}` : '';

    this.basemaps = {
      positron: L.tileLayer(`https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png${keyParam}`, {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
        subdomains: 'abcd',
        maxZoom: 20
      }),
      voyager: L.tileLayer(`https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png${keyParam}`, {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
        subdomains: 'abcd',
        maxZoom: 20
      }),
      dark: L.tileLayer(`https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png${keyParam}`, {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
        subdomains: 'abcd',
        maxZoom: 20
      }),
      satellite: L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
        attribution: 'Tiles &copy; Esri &mdash; Reggio Emilia',
        maxZoom: 19
      })
    };

    // Default: CARTO Positron
    this.currentBasemap = 'positron';
    this.basemaps.positron.addTo(this.map);

    // 1. Inizializza layer coropletico dei Quartieri/Ambiti
    this.initQuartieriLayer();

    // 2. Inizializza layer lettere Ambiti (A-H, CS)
    this.initAmbitiLetters();

    // 3. Aggiungi il layer dei marker sopra i poligoni
    this.markersLayer.addTo(this.map);

    // Trasparenza zoom profondo
    this.map.on('zoomend', () => {
      const z = this.map.getZoom();
      if (this.quartieriLayer && this.isChoroplethVisible) {
        this.quartieriLayer.eachLayer(layer => {
          if (z >= 15) {
            layer.setStyle({ fillOpacity: 0.18, weight: 1.5 });
          } else {
            const originalOpacity = layer.options.originalFillOpacity || 0.45;
            layer.setStyle({ fillOpacity: originalOpacity, weight: 2 });
          }
        });
      }
    });

    // Click sul vuoto della mappa deseleziona
    this.map.on('click', () => {
      if (this.selectedArea) {
        if (this.onAmbitoSelect) {
          this.onAmbitoSelect(null);
        }
      }
    });
  }

  initQuartieriLayer() {
    this.quartieriLayer = L.geoJSON(QUARTIERI_GEOJSON, {
      style: () => ({
        color: '#0E8C9B',
        weight: 1.5,
        opacity: 0.7,
        fillColor: '#5AC8D8',
        fillOpacity: 0.4,
        dashArray: '2, 3'
      }),
      onEachFeature: (feature, layer) => {
        const p = feature.properties;
        const qName = p.name || p.quartiere;
        const ambitoNome = p.ambitoNome || 'Ambito H';

        layer.on({
          mouseover: (e) => {
            const l = e.target;
            l.setStyle({
              weight: 3.5,
              opacity: 1,
              color: '#085C66',
              fillOpacity: 0.85,
              dashArray: null
            });
            l.bringToFront();
            if (this.markersLayer) {
              this.markersLayer.bringToFront();
            }
          },
          mouseout: (e) => {
            if (this.selectedArea === qName || this.selectedArea === ambitoNome) {
              e.target.setStyle({
                weight: 4,
                color: '#0E8C9B',
                opacity: 1,
                fillOpacity: 0.75
              });
            } else {
              this.applyStyleToFeature(e.target, feature);
            }
          },
          click: (e) => {
            if (e && e.originalEvent) {
              e.originalEvent.stopPropagation();
            }
            const isCurrentlySelected = this.selectedArea === ambitoNome || this.selectedArea === qName;
            if (isCurrentlySelected) {
              if (this.onAmbitoSelect) {
                this.onAmbitoSelect(null);
              }
            } else {
              // Filtra a livello di Ambito per la massima coerenza analitica
              if (this.onAmbitoSelect) {
                this.onAmbitoSelect(ambitoNome);
              }
            }
          }
        });
      }
    });

    this.quartieriLayer.addTo(this.map);
  }

  initAmbitiLetters() {
    this.ambitiLettersLayer = L.layerGroup();
    this.renderAmbitiLetters();
    this.ambitiLettersLayer.addTo(this.map);
  }

  renderAmbitiLetters() {
    this.ambitiLettersLayer.clearLayers();

    const hasSelectedArea = Boolean(this.selectedArea);

    AMBITI_CENTROIDS.forEach(a => {
      const stats = this.ambitiData[a.name] || { count: 0, totalFunding: 0, metricValue: 0 };
      const formattedVal = this.choroplethScale 
        ? this.choroplethScale.formatValue(stats.metricValue)
        : `${(stats.totalFunding / 1000000).toFixed(1)} M€`;

      const isSelected = hasSelectedArea && (this.selectedArea === a.name);

      let containerClasses = 'ambito-letter-pill flex flex-col items-center cursor-pointer group select-none transition-all duration-200';
      let circleClasses = 'ambito-letter-circle h-8 w-8 md:h-9 md:w-9 rounded-full font-black text-xs md:text-sm flex items-center justify-center transition-all';
      let pillClasses = 'mt-1 px-2 py-0.5 rounded-full shadow-card text-center flex flex-col leading-none transition-all';

      if (isSelected) {
        // Selezionato: ingrandito, evidente con ring teal e sfondo scuro
        containerClasses += ' scale-125 z-50';
        circleClasses += ' bg-[#085C66] text-white shadow-float ring-4 ring-teal/40 border-2 border-white';
        pillClasses += ' bg-teal text-white border border-teal font-black shadow-md';
      } else if (hasSelectedArea) {
        // Altro ambito quando uno è selezionato: attenuato
        containerClasses += ' opacity-40 scale-90';
        circleClasses += ' bg-slate-400 text-white border border-white';
        pillClasses += ' bg-white/85 text-ink/60 border border-ink/10';
      } else {
        // TUTTI GLI AMBITI: tutti uguali, puliti e bilanciati
        circleClasses += ' bg-[#0E8C9B] hover:bg-[#085C66] text-white shadow-float border-2 border-white';
        pillClasses += ' bg-white/95 backdrop-blur-md border border-ink/10 hover:border-teal/30';
      }

      const letterIcon = L.divIcon({
        className: 'pnrr-ambito-letter-container',
        html: `
          <div class="${containerClasses}" title="${a.name}: ${stats.count} progetti (${formattedVal})">
            <div class="${circleClasses}">
              ${a.lettera}
            </div>
            <div class="${pillClasses}">
              <span class="text-[9px] ${isSelected ? 'text-white font-black' : 'text-ink font-bold'} whitespace-nowrap">${a.name}</span>
              <span class="text-[8.5px] ${isSelected ? 'text-teal-100 font-extrabold' : 'text-teal font-extrabold'}">${formattedVal}</span>
            </div>
          </div>
        `,
        iconSize: [40, 52],
        iconAnchor: [20, 20]
      });

      const marker = L.marker([a.lat, a.lng], {
        icon: letterIcon,
        riseOnHover: true,
        zIndexOffset: isSelected ? 500 : 100
      });

      marker.on('click', (e) => {
        if (e && e.originalEvent) e.originalEvent.stopPropagation();
        if (this.onAmbitoSelect) {
          const next = this.selectedArea === a.name ? null : a.name;
          this.onAmbitoSelect(next);
        }
      });

      this.ambitiLettersLayer.addLayer(marker);
    });
  }

  /**
   * Aggiorna i dati coropletici per Ambito e ricalcola i poligoni e i tooltip
   */
  updateChoropleth(ambitiData, scale) {
    this.ambitiData = ambitiData;
    this.choroplethScale = scale;

    if (this.quartieriLayer) {
      this.quartieriLayer.eachLayer(layer => {
        const feature = layer.feature;
        this.applyStyleToFeature(layer, feature);
        this.bindAmbitoTooltip(layer, feature);
      });
    }

    this.renderAmbitiLetters();
  }

  applyStyleToFeature(layer, feature) {
    const p = feature.properties;
    const ambitoNome = p.ambitoNome || 'Ambito H';
    const qName = p.name || p.quartiere;
    const ambitoStats = this.ambitiData[ambitoNome];

    let color = '#A2DFE8';
    let fillOpacity = 0.35;

    if (this.choroplethScale && ambitoStats) {
      const val = this.choroplethScale.getValue(ambitoStats);
      const thresholds = this.choroplethScale.thresholds;

      for (let i = 0; i < thresholds.length; i++) {
        if (val <= thresholds[i].max) {
          color = thresholds[i].color;
          fillOpacity = thresholds[i].fillOpacity || 0.40;
          break;
        }
      }
    } else if (!ambitoStats || ambitoStats.count === 0) {
      color = '#E2E8F0';
      fillOpacity = 0.15;
    }

    layer.options.originalFillOpacity = fillOpacity;

    const hasSelectedArea = Boolean(this.selectedArea);
    const isSelected = Boolean(this.selectedArea && (this.selectedArea === ambitoNome || this.selectedArea === qName || (ambitoNome && this.selectedArea.includes(ambitoNome))));

    if (isSelected) {
      layer.setStyle({
        fillColor: color,
        fillOpacity: 0.82,
        color: '#085C66',
        weight: 3.5,
        opacity: 1,
        dashArray: null
      });
    } else if (hasSelectedArea) {
      // Un altro ambito è selezionato -> attenua questo
      layer.setStyle({
        fillColor: color,
        fillOpacity: 0.08,
        color: '#94A3B8',
        weight: 0.8,
        opacity: 0.25,
        dashArray: '2, 3'
      });
    } else {
      // TUTTI GLI AMBITI: stile pulito, bilanciato e uniforme per tutta la città
      layer.setStyle({
        fillColor: color,
        fillOpacity: fillOpacity,
        color: '#0E8C9B',
        weight: 1.2,
        opacity: 0.55,
        dashArray: '2, 2'
      });
    }
  }

  formatMillions(amount) {
    if (!amount) return '0,0 M';
    if (amount >= 1000000) {
      return (amount / 1000000).toLocaleString('it-IT', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' M';
    }
    return Math.round(amount / 1000).toLocaleString('it-IT') + ' k';
  }

  /**
   * Tooltip rigorosamente formattato secondo il requisito dell'utente:
   * AMBITO E
   * 14 progetti
   * € 18,4 M investiti
   * € 11,2 M PNRR
   * € 6,1 M pagati
   * 54% avanzamento medio
   */
  bindAmbitoTooltip(layer, feature) {
    const p = feature.properties;
    const qName = p.name || p.quartiere;
    const ambitoNome = p.ambitoNome || 'Ambito H';
    const stats = this.ambitiData[ambitoNome] || {
      name: ambitoNome,
      count: 0,
      totalFunding: 0,
      pnrrFunding: 0,
      payments: 0,
      avgProgress: 0
    };

    const countText = `${stats.count} ${stats.count === 1 ? 'progetto' : 'progetti'}`;

    layer.bindTooltip(`
      <div class="p-3 font-sans text-left min-w-[210px] max-w-[280px] text-ink select-none leading-tight">
        <div class="flex items-center justify-between gap-1.5 mb-2 pb-1.5 border-b border-ink/10">
          <span class="text-[14px] font-black uppercase text-teal tracking-tight">
            ${ambitoNome}
          </span>
          <span class="text-[10px] font-bold text-ink-muted truncate">
            ${qName}
          </span>
        </div>

        <div class="space-y-1.5 text-[12px]">
          <div class="font-extrabold text-ink text-[13px]">
            ${countText}
          </div>
          <div class="text-ink">
            <strong>€ ${this.formatMillions(stats.totalFunding)}</strong> investiti
          </div>
          <div class="text-blue-700 font-semibold">
            <strong>€ ${this.formatMillions(stats.pnrrFunding)}</strong> PNRR
          </div>
          <div class="text-emerald-700 font-semibold">
            <strong>€ ${this.formatMillions(stats.payments)}</strong> pagati
          </div>
          <div class="text-teal font-black pt-0.5 text-[12.5px]">
            <strong>${stats.avgProgress}%</strong> avanzamento medio
          </div>
        </div>

        <div class="mt-2.5 pt-1.5 border-t border-ink/8 text-[9.5px] font-bold text-teal text-center uppercase tracking-wide">
          ${this.selectedArea === ambitoNome ? '✓ Ambito attivo · Clicca per mostrare tutti gli ambiti' : 'Clicca per filtrare su questo Ambito'}
        </div>
      </div>
    `, {
      sticky: true,
      direction: 'auto',
      className: 'radar-pnrr-quartiere-tooltip'
    });
  }

  /**
   * Aggiorna i marker dei progetti sulla mappa
   */
  setProjects(projects = [], activeCup = null) {
    this.projects = projects;
    this.currentActiveCup = activeCup;
    this.markersLayer.clearLayers();

    projects.forEach(project => {
      if (project.latitude && project.longitude) {
        const isActive = project.cup === activeCup;
        const marker = createProjectMarker(
          project, 
          (p) => {
            this.setActiveMarker(p.cup);
            if (this.onProjectSelect) {
              this.onProjectSelect(p);
            }
          }, 
          isActive
        );
        this.markersLayer.addLayer(marker);
      }
    });
  }

  setActiveMarker(cup) {
    this.currentActiveCup = cup;
    this.markersLayer.eachLayer(layer => {
      if (layer instanceof L.Marker && layer.options.title) {
        const el = layer.getElement();
        if (el) {
          const markerCup = el.getAttribute('data-cup');
          if (markerCup === cup) {
            el.classList.add('scale-125', 'z-50');
          } else {
            el.classList.remove('scale-125', 'z-50');
          }
        }
      }
    });
  }

  focusProject(project) {
    if (!project || !project.latitude || !project.longitude) return;

    this.map.flyTo([project.latitude, project.longitude], 16, {
      animate: true,
      duration: 1.2
    });

    this.setActiveMarker(project.cup);
  }

  highlightArea(areaName) {
    const isAll = !areaName || 
      areaName === 'Tutta Reggio Emilia' || 
      areaName === 'Tutti i quartieri' || 
      areaName === 'Tutti gli ambiti' || 
      areaName === 'Tutti gli Ambiti' || 
      areaName === 'Tutti' || 
      areaName === 'tutti' || 
      areaName === 'all';

    this.selectedArea = isAll ? null : areaName;

    if (!this.selectedArea) {
      this.resetToDefaultView();
      this.resetQuartieriStyle();
      return;
    }

    let targetBounds = null;

    if (this.quartieriLayer) {
      this.quartieriLayer.eachLayer(layer => {
        const p = layer.feature.properties;
        const qName = p.name || p.quartiere;
        const ambitoNome = p.ambitoNome;
        const matches = qName === this.selectedArea || ambitoNome === this.selectedArea || (this.selectedArea && this.selectedArea.includes(ambitoNome));

        if (matches) {
          if (!targetBounds) {
            targetBounds = layer.getBounds();
          } else {
            targetBounds.extend(layer.getBounds());
          }
        }
        this.applyStyleToFeature(layer, layer.feature);
      });
    }

    this.renderAmbitiLetters();

    if (targetBounds && targetBounds.isValid()) {
      this.map.fitBounds(targetBounds, {
        padding: [40, 40],
        maxZoom: 15,
        animate: true,
        duration: 0.8
      });
    }
  }

  resetQuartieriStyle() {
    this.selectedArea = null;
    if (this.quartieriLayer) {
      this.quartieriLayer.eachLayer(layer => {
        this.applyStyleToFeature(layer, layer.feature);
      });
    }
    this.renderAmbitiLetters();
  }

  resetToDefaultView() {
    this.map.flyTo(this.defaultCenter, this.defaultZoom, {
      animate: true,
      duration: 0.8
    });
  }

  setBasemap(name) {
    if (this.basemaps[name] && name !== this.currentBasemap) {
      this.map.removeLayer(this.basemaps[this.currentBasemap]);
      this.basemaps[name].addTo(this.map);
      this.currentBasemap = name;
      if (this.quartieriLayer) {
        this.quartieriLayer.bringToFront();
      }
      if (this.markersLayer) {
        this.markersLayer.bringToFront();
      }
    }
  }

  setChoroplethVisible(visible) {
    this.isChoroplethVisible = visible;
    if (visible) {
      if (!this.map.hasLayer(this.quartieriLayer)) {
        this.quartieriLayer.addTo(this.map);
      }
    } else {
      if (this.map.hasLayer(this.quartieriLayer)) {
        this.map.removeLayer(this.quartieriLayer);
      }
    }
  }

  showAddressMarker(lat, lng, label) {
    if (this.searchMarker) {
      this.map.removeLayer(this.searchMarker);
    }

    const pinIcon = L.divIcon({
      className: 'custom-search-pin',
      html: `
        <div class="flex flex-col items-center select-none animate-bounce">
          <div class="h-9 w-9 rounded-full bg-teal text-white flex items-center justify-center shadow-float border-2 border-white">
            <i class="ph-bold ph-map-pin text-lg"></i>
          </div>
          <span class="mt-1 px-2.5 py-0.5 rounded-full bg-ink/90 text-white text-[10px] font-black shadow-card truncate max-w-[160px]">
            ${label}
          </span>
        </div>
      `,
      iconSize: [36, 44],
      iconAnchor: [18, 44]
    });

    this.searchMarker = L.marker([lat, lng], { icon: pinIcon }).addTo(this.map);
    this.map.flyTo([lat, lng], 16, { animate: true, duration: 1.0 });
  }

  setUserLocation(lat, lng, accuracy = 20) {
    if (this.userLocationMarker) this.map.removeLayer(this.userLocationMarker);
    if (this.userAccuracyCircle) this.map.removeLayer(this.userAccuracyCircle);

    const userIcon = L.divIcon({
      className: 'custom-user-location',
      html: `
        <div class="relative flex items-center justify-center h-6 w-6">
          <span class="animate-ping absolute inline-flex h-full w-full rounded-full bg-teal opacity-75"></span>
          <span class="relative inline-flex rounded-full h-4 w-4 bg-teal border-2 border-white shadow-float"></span>
        </div>
      `,
      iconSize: [24, 24],
      iconAnchor: [12, 12]
    });

    this.userLocationMarker = L.marker([lat, lng], { icon: userIcon, zIndexOffset: 1000 }).addTo(this.map);
    this.userAccuracyCircle = L.circle([lat, lng], {
      radius: accuracy,
      color: '#0E8C9B',
      fillColor: '#0E8C9B',
      fillOpacity: 0.12,
      weight: 1
    }).addTo(this.map);

    this.map.flyTo([lat, lng], 15, { animate: true, duration: 1.0 });
  }
}
