/**
 * REGGIO PNRR / RadarPNRR — Right Sidebar Component
 * "Progetti PNRR" — Elenco navigabile degli interventi con filtri rapidi avanzati
 */

import { renderProjectCard } from './projectCard.js';
import { PNRR_MISSIONS } from '../data/projectsData.js';

export class RightSidebar {
  constructor(containerEl, onProjectSelect, onFilterChange) {
    this.container = containerEl;
    this.onProjectSelect = onProjectSelect;
    this.onFilterChange = onFilterChange;

    this.projects = [];
    this.activeCup = null;
    this.filters = {
      type: 'tutti',       // 'tutti' | 'opere' | 'digitale' | 'servizi'
      status: 'tutti',     // 'tutti' | 'in_corso' | 'completato' | 'in_ritardo'
      mission: null        // null | 'M1' .. 'M6'
    };

    this.render();
  }

  setProjects(projects, activeCup = null, totalAvailable = projects.length) {
    this.projects = projects;
    this.activeCup = activeCup;
    this.totalAvailable = totalAvailable;
    this.updateProjectsList();
    this.updateHeaderCounts();
  }

  setActiveCup(cup) {
    this.activeCup = cup;
    const cards = this.container.querySelectorAll('.project-card-item');
    cards.forEach(card => {
      if (card.getAttribute('data-cup') === cup) {
        card.classList.add('border-teal', 'bg-teal-soft/80', 'ring-1', 'ring-teal');
        card.classList.remove('border-ink/8', 'bg-white');
        card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      } else {
        card.classList.remove('border-teal', 'bg-teal-soft/80', 'ring-1', 'ring-teal');
        card.classList.add('border-ink/8', 'bg-white');
      }
    });
  }

  setFiltersState(filters) {
    this.filters = { ...this.filters, ...filters };
    this.updateFilterButtons();
  }

  render() {
    this.container.innerHTML = `
      <!-- Panel Header -->
      <div class="flex shrink-0 items-center justify-between gap-2 border-b border-ink/8 px-4 py-3.5 bg-white">
        <div>
          <div class="flex items-baseline gap-1.5">
            <span id="right-sidebar-count" class="text-[16px] font-black text-ink">
              ${this.projects.length} progetti PNRR
            </span>
          </div>
          <p class="text-[11px] font-bold text-teal">
            Investimenti localizzati nel Comune di Reggio Emilia
          </p>
        </div>

        <button 
          type="button" 
          id="toggle-right-sidebar-btn" 
          class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-ink/50 hover:bg-ink/5 hover:text-ink transition-colors"
          title="Nascondi pannello progetti"
          aria-label="Nascondi progetti"
        >
          <i class="ph-bold ph-caret-right text-base"></i>
        </button>
      </div>

      <!-- Quick Filter Bar (Integrated into Sidebar) -->
      <div class="shrink-0 border-b border-ink/8 px-3.5 py-2.5 bg-surface-subtle/80 select-none space-y-2">
        <!-- Row 1: Status Filters -->
        <div class="flex items-center justify-between gap-1 text-[10.5px]">
          <span class="font-extrabold text-ink-muted text-[10px] uppercase tracking-wider shrink-0">Stato:</span>
          <div class="flex items-center gap-1 overflow-x-auto">
            <button 
              type="button" 
              class="status-chip px-2.5 py-0.5 rounded-full border transition-all ${this.filters.status === 'tutti' ? 'bg-teal text-white border-teal font-black shadow-xs' : 'bg-white border-ink/10 text-ink/70 hover:border-teal'}"
              data-status="tutti"
            >
              Tutti
            </button>
            <button 
              type="button" 
              class="status-chip px-2.5 py-0.5 rounded-full border transition-all ${this.filters.status === 'in_corso' ? 'bg-amber-100 text-amber-900 border-amber-300 font-black ring-1 ring-amber-400' : 'bg-white border-ink/10 text-ink/70 hover:border-teal'}"
              data-status="in_corso"
            >
              In corso
            </button>
            <button 
              type="button" 
              class="status-chip px-2.5 py-0.5 rounded-full border transition-all ${this.filters.status === 'completato' ? 'bg-emerald-100 text-emerald-900 border-emerald-300 font-black ring-1 ring-emerald-400' : 'bg-white border-ink/10 text-ink/70 hover:border-teal'}"
              data-status="completato"
            >
              Completati
            </button>
          </div>
        </div>

        <!-- Row 2: Mission Pills (M1 - M6) -->
        <div class="flex items-center justify-between gap-1">
          <span class="font-extrabold text-ink-muted text-[10px] uppercase tracking-wider shrink-0">Missione:</span>
          <div class="flex items-center gap-1">
            <button 
              type="button" 
              class="mission-pill-chip h-6 px-2 rounded-md text-[10px] font-bold border transition-all ${!this.filters.mission ? 'bg-ink/80 text-white font-black' : 'bg-white border-ink/10 text-ink/60 hover:bg-ink/5'}"
              data-mission="tutte"
              title="Tutte le Missioni PNRR"
            >
              Tutte
            </button>
            ${Object.keys(PNRR_MISSIONS).map(mKey => {
              const isSelected = this.filters.mission === mKey;
              const mData = PNRR_MISSIONS[mKey];
              return `
                <button 
                  type="button" 
                  class="mission-pill-chip h-6 w-7 shrink-0 rounded-md text-[10px] font-black flex items-center justify-center transition-all ${isSelected ? 'ring-2 ring-ink text-white font-black scale-105 shadow-sm' : 'opacity-80 hover:opacity-100 hover:scale-105'}"
                  style="background-color: ${mData.color}; color: white;"
                  data-mission="${mKey}"
                  title="${mKey} — ${mData.name}"
                >
                  ${mKey}
                </button>
              `;
            }).join('')}
          </div>
        </div>
      </div>

      <!-- Projects Scrollable List -->
      <div class="flex-1 overflow-y-auto overscroll-contain custom-scrollbar p-3">
        <div id="projects-list-container" class="flex flex-col gap-2.5">
          <!-- Cards injected here -->
        </div>
      </div>
    `;

    this.bindEvents();
    this.updateProjectsList();
  }

  updateHeaderCounts() {
    const countEl = this.container.querySelector('#right-sidebar-count');
    if (countEl) {
      countEl.innerText = `${this.projects.length} progetti PNRR`;
    }
  }

  updateProjectsList() {
    const listContainer = this.container.querySelector('#projects-list-container');
    if (!listContainer) return;

    if (this.projects.length === 0) {
      listContainer.innerHTML = `
        <div class="flex flex-col items-center justify-center p-8 text-center text-ink-muted">
          <div class="h-12 w-12 rounded-full bg-ink/5 flex items-center justify-center mb-3">
            <i class="ph ph-magnifying-glass text-2xl text-ink/40"></i>
          </div>
          <p class="font-bold text-ink text-[15px]">Nessun progetto trovato</p>
          <p class="text-xs text-ink/60 mt-1 max-w-[220px]">
            Prova a reimpostare i filtri di perimetro o la ricerca per esplorare gli altri interventi.
          </p>
        </div>
      `;
      return;
    }

    listContainer.innerHTML = this.projects.map(p => {
      return renderProjectCard(p, p.cup === this.activeCup);
    }).join('');

    // Attach click listeners to cards
    listContainer.querySelectorAll('.project-card-item').forEach(card => {
      card.addEventListener('click', () => {
        const cup = card.getAttribute('data-cup');
        const project = this.projects.find(p => p.cup === cup);
        if (project && this.onProjectSelect) {
          this.setActiveCup(cup);
          this.onProjectSelect(project);
        }
      });
    });
  }

  updateFilterButtons() {
    // Update status chips styles
    const activeStatus = this.filters.status || 'tutti';
    this.container.querySelectorAll('.status-chip').forEach(b => {
      const st = b.getAttribute('data-status');
      const isSelected = st === activeStatus;
      if (st === 'tutti') {
        b.className = `status-chip px-2.5 py-0.5 rounded-full border transition-all ${isSelected ? 'bg-teal text-white border-teal font-black shadow-xs' : 'bg-white border-ink/10 text-ink/70 hover:border-teal'}`;
      } else if (st === 'in_corso') {
        b.className = `status-chip px-2.5 py-0.5 rounded-full border transition-all ${isSelected ? 'bg-amber-100 text-amber-900 border-amber-300 font-black ring-1 ring-amber-400' : 'bg-white border-ink/10 text-ink/70 hover:border-teal'}`;
      } else if (st === 'completato') {
        b.className = `status-chip px-2.5 py-0.5 rounded-full border transition-all ${isSelected ? 'bg-emerald-100 text-emerald-900 border-emerald-300 font-black ring-1 ring-emerald-400' : 'bg-white border-ink/10 text-ink/70 hover:border-teal'}`;
      }
    });

    // Update mission chips styles
    const activeMission = this.filters.mission;
    this.container.querySelectorAll('.mission-pill-chip').forEach(b => {
      const m = b.getAttribute('data-mission');
      if (m === 'tutte' || !m) {
        const isSelected = !activeMission || activeMission === 'tutte';
        b.className = `mission-pill-chip h-6 px-2 rounded-md text-[10px] font-bold border transition-all ${isSelected ? 'bg-ink/80 text-white font-black' : 'bg-white border-ink/10 text-ink/60 hover:bg-ink/5'}`;
      } else {
        const isSelected = m === activeMission;
        b.className = `mission-pill-chip h-6 w-7 shrink-0 rounded-md text-[10px] font-black flex items-center justify-center transition-all ${isSelected ? 'ring-2 ring-ink text-white font-black scale-105 shadow-sm' : 'opacity-80 hover:opacity-100 hover:scale-105'}`;
      }
    });
  }

  bindEvents() {
    // Status filters
    this.container.querySelectorAll('.status-chip').forEach(b => {
      b.addEventListener('click', () => {
        const clickedStatus = b.getAttribute('data-status');
        const nextStatus = (this.filters.status === clickedStatus && clickedStatus !== 'tutti') 
          ? 'tutti' 
          : clickedStatus;
        this.filters.status = nextStatus;
        this.updateFilterButtons();
        if (this.onFilterChange) this.onFilterChange({ status: nextStatus });
      });
    });

    // Mission pills
    this.container.querySelectorAll('.mission-pill-chip').forEach(b => {
      b.addEventListener('click', () => {
        const clickedMission = b.getAttribute('data-mission');
        const targetMission = (clickedMission === 'tutte' || !clickedMission) ? null : clickedMission;
        const nextMission = (this.filters.mission === targetMission && targetMission !== null)
          ? null
          : targetMission;
        this.filters.mission = nextMission;
        this.updateFilterButtons();
        if (this.onFilterChange) this.onFilterChange({ mission: nextMission });
      });
    });
  }
}
