/**
 * REGGIO PNRR / RadarPNRR — Servizio ETL, Data Quality & PNRR Pulse
 * - Gestione unione sorgenti (OpenPNRR / Italia Domani + Dataset Comune di Reggio Emilia)
 * - Calcolo Data Quality Index
 * - Calcolo Indicatore di Performance "PNRR Pulse" (0 - 100)
 */

/**
 * Normalizza e pulisce un codice CUP per il matching
 */
export function normalizeCUP(cup) {
  if (!cup) return '';
  return String(cup).trim().toUpperCase();
}

/**
 * Unione e riconciliazione tra dataset nazionale (Italia Domani / OpenPNRR)
 * e dataset territoriale del Comune di Reggio Emilia.
 * Regola cardine: MATCHING SU CUP.
 */
export function mergeProjectDatasets(nationalDataset = [], comuneDataset = []) {
  const mergedMap = new Map();

  // 1. Mappa i dati comunali per CUP
  const comuneMap = new Map();
  comuneDataset.forEach(comuneItem => {
    const cleanCup = normalizeCUP(comuneItem.cup);
    if (cleanCup) {
      comuneMap.set(cleanCup, comuneItem);
    }
  });

  // 2. Itera sui record nazionali e fa il match
  nationalDataset.forEach(natItem => {
    const cup = normalizeCUP(natItem.cup);
    const localMatch = comuneMap.get(cup);

    if (localMatch) {
      // Regole di priorità:
      // - Finanziario: fonte nazionale
      // - Localizzazione e coordinate: fonte comunale
      // - Avanzamento fisico e cantiere: fonte comunale
      const merged = {
        ...natItem,
        ...localMatch,
        // Dati finanziari ufficiali prioritari dalla fonte nazionale
        totalFunding: natItem.totalFunding ?? localMatch.totalFunding ?? 0,
        pnrrFunding: natItem.pnrrFunding ?? localMatch.pnrrFunding ?? 0,
        otherFunding: natItem.otherFunding ?? localMatch.otherFunding ?? 0,
        payments: natItem.payments ?? localMatch.payments ?? 0,
        paymentPercentage: natItem.totalFunding > 0 
          ? Math.round(((natItem.payments || 0) / natItem.totalFunding) * 1000) / 10 
          : (localMatch.paymentPercentage || 0),
        // Localizzazione e monitoraggio fisico prioritari dal Comune
        address: localMatch.address || natItem.address || '',
        latitude: localMatch.latitude || natItem.latitude || null,
        longitude: localMatch.longitude || natItem.longitude || null,
        district: localMatch.district || natItem.district || 'Reggio Emilia',
        area: localMatch.area || natItem.area || 'Ambito H',
        progress: localMatch.progress ?? natItem.progress ?? 0,
        status: localMatch.status || natItem.status || 'in_corso',
        sources: {
          financial: natItem.source || 'Italia Domani / OpenPNRR',
          location: 'Comune di Reggio Emilia',
          monitoring: 'Comune di Reggio Emilia'
        },
        sourceUpdateDate: localMatch.sourceUpdateDate || natItem.sourceUpdateDate || 'Aggiornato di recente'
      };
      mergedMap.set(cup, merged);
      comuneMap.delete(cup); // rimosso perché già unito
    } else {
      // Solo fonte nazionale
      mergedMap.set(cup, {
        ...natItem,
        sources: {
          financial: natItem.source || 'Italia Domani / OpenPNRR',
          location: 'Italia Domani',
          monitoring: 'OpenPNRR'
        }
      });
    }
  });

  // 3. Aggiungi eventuali progetti locali comunali non ancora censiti nel nazionale
  comuneMap.forEach((localItem, cup) => {
    mergedMap.set(cup, {
      ...localItem,
      sources: {
        financial: 'Comune di Reggio Emilia (Previsione)',
        location: 'Comune di Reggio Emilia',
        monitoring: 'Comune di Reggio Emilia'
      }
    });
  });

  return Array.from(mergedMap.values());
}

/**
 * Valutazione della qualità del dato di un singolo progetto.
 * Restituisce un punteggio da 0 a 100 e l'elenco dei campi mancanti.
 */
export function calculateProjectDataQuality(project) {
  if (!project) return { score: 0, missingFields: ['Oggetto nullo'] };

  const checks = [
    { field: 'cup', label: 'CUP valido', test: (p) => Boolean(p.cup && p.cup.length >= 10) },
    { field: 'coordinates', label: 'Coordinate georeferenziate', test: (p) => Boolean(p.latitude && p.longitude && p.latitude > 44.5 && p.latitude < 44.9) },
    { field: 'totalFunding', label: 'Importo totale presente', test: (p) => typeof p.totalFunding === 'number' && p.totalFunding > 0 },
    { field: 'pnrrFunding', label: 'Quota PNRR specificata', test: (p) => typeof p.pnrrFunding === 'number' && p.pnrrFunding > 0 },
    { field: 'implementingBody', label: 'Soggetto attuatore', test: (p) => Boolean(p.implementingBody && p.implementingBody.trim()) },
    { field: 'status', label: 'Stato procedurale', test: (p) => Boolean(p.status) },
    { field: 'schedule', label: 'Cronoprogramma (date)', test: (p) => Boolean(p.startDate && p.expectedEndDate) },
    { field: 'payments', label: 'Stato pagamenti', test: (p) => typeof p.payments === 'number' }
  ];

  const missing = [];
  let passed = 0;

  checks.forEach(c => {
    if (c.test(project)) {
      passed++;
    } else {
      missing.push(c.label);
    }
  });

  const score = Math.round((passed / checks.length) * 100);
  return {
    score,
    passedCount: passed,
    totalCount: checks.length,
    missingFields: missing,
    isComplete: missing.length === 0
  };
}

/**
 * Calcolo della completezza complessiva di un set di progetti
 */
export function calculateDataQualitySummary(projects = []) {
  if (!projects || projects.length === 0) {
    return { averageScore: 0, label: 'Nessun dato', totalProjects: 0, fullyCompleteProjects: 0 };
  }

  let totalScore = 0;
  let fullCount = 0;

  projects.forEach(p => {
    const q = calculateProjectDataQuality(p);
    totalScore += q.score;
    if (q.isComplete) fullCount++;
  });

  const avg = Math.round(totalScore / projects.length);
  return {
    averageScore: avg,
    totalProjects: projects.length,
    fullyCompleteProjects: fullCount,
    percentageCompleteProjects: Math.round((fullCount / projects.length) * 100)
  };
}

/**
 * PNRR PULSE — Indicatore sintetico sperimentale di salute e avanzamento del portafoglio (0 - 100)
 * Pesi:
 * - 40% avanzamento finanziario (% pagamenti effettivi sul totale)
 * - 30% avanzamento fisico/procedurale (media % avanzamento cantiere o fornitura)
 * - 20% rispetto cronoprogramma (% progetti non in ritardo critico)
 * - 10% qualità e completezza del dato
 */
export function calculatePnrrPulse(projects = []) {
  if (!projects || projects.length < 2) {
    return {
      score: null,
      label: 'Dati insufficienti',
      color: '#889DA5',
      badgeClass: 'bg-slate-100 text-slate-700 border-slate-300',
      reason: 'Numero di progetti insufficiente per un calcolo statistico affidabile.',
      financialComponent: 0,
      physicalComponent: 0,
      scheduleComponent: 0,
      qualityComponent: 0
    };
  }

  // 1. Avanzamento finanziario pesato (40%)
  let totalBudget = 0;
  let totalPayments = 0;
  let totalPhysicalProgress = 0;
  let onScheduleCount = 0;

  projects.forEach(p => {
    totalBudget += (p.totalFunding || 0);
    totalPayments += (p.payments || 0);
    totalPhysicalProgress += (p.progress || 0);
    if (p.status !== 'in_ritardo') {
      onScheduleCount++;
    }
  });

  const financialRate = totalBudget > 0 ? Math.min(100, (totalPayments / totalBudget) * 100) : 0;
  const financialScore = financialRate * 0.40;

  // 2. Avanzamento fisico medio (30%)
  const avgPhysical = totalPhysicalProgress / projects.length;
  const physicalScore = avgPhysical * 0.30;

  // 3. Rispetto del cronoprogramma (20%)
  const scheduleRate = (onScheduleCount / projects.length) * 100;
  const scheduleScore = scheduleRate * 0.20;

  // 4. Qualità del dato (10%)
  const dq = calculateDataQualitySummary(projects);
  const qualityScore = dq.averageScore * 0.10;

  const totalScore = Math.round(financialScore + physicalScore + scheduleScore + qualityScore);

  let label = 'REGOLARE';
  let color = '#10B981'; // emerald
  let badgeClass = 'bg-emerald-50 text-emerald-700 border-emerald-200';

  if (totalScore >= 80) {
    label = 'ELEVATO';
    color = '#0E8C9B';
    badgeClass = 'bg-teal-50 text-teal-dark border-teal/30';
  } else if (totalScore >= 60) {
    label = 'REGOLARE';
    color = '#10B981';
    badgeClass = 'bg-emerald-50 text-emerald-700 border-emerald-200';
  } else if (totalScore >= 40) {
    label = 'ATTENZIONE';
    color = '#F59E0B';
    badgeClass = 'bg-amber-50 text-amber-800 border-amber-300';
  } else {
    label = 'CRITICITÀ';
    color = '#EF4444';
    badgeClass = 'bg-rose-50 text-rose-700 border-rose-300';
  }

  return {
    score: totalScore,
    label,
    color,
    badgeClass,
    reason: `Calcolato su ${projects.length} interventi in monitoraggio.`,
    financialRate: Math.round(financialRate),
    physicalRate: Math.round(avgPhysical),
    scheduleRate: Math.round(scheduleRate),
    qualityRate: Math.round(dq.averageScore),
    components: {
      financial: Math.round(financialScore),
      physical: Math.round(physicalScore),
      schedule: Math.round(scheduleScore),
      quality: Math.round(qualityScore)
    }
  };
}
